        // GET: ProvidedInfo
        [SessionExpireFilterAttribute]
        public ActionResult Index()
        {
            try
            {
                CreateNavigationforTeamMemberDE();
                short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                string Designation = Session["Designation"].ToString();
                Session["Search"] = "";

                //DataEntry Manager
                if (Designation == "Manager-DE")
                {
                    ViewBag.DEDashboard = "DataEntry Manager Dashboard!";
                    ViewBag.DEManagerDashboard = repoIDashboardDataEntry.GetDEManagerDashBoardInfo(teamMemerRowId, Designation);
                }
                //DataEntry TeamLeader               
                if (Designation == "Team Leader-DE")
                {
                    ViewBag.DEDashboard = "DataEntry TeamLeader Dashboard!";
                    ViewBag.DETeamLeaderDashboard = repoIDashboardDataEntry.GetDETeamLeaderDashBoardInfo(teamMemerRowId, Designation);
                    //CreateNavigationforInsuffCaseForTL();
                }

                //DataEntry Team Member-DE-Scan               
                if (Designation == "Team Member-DE-Scan")
                {
                    ViewBag.DEDashboard = "DataEntry TeamMember Scanner Dashboard!";
                    ViewBag.DEScanTeamMemberDashboard = repoIDashboardDataEntry.GetDETeamMemberDEScanDashBoardInfo(teamMemerRowId, Designation);
                }

                //DataEntry Team Member-DE               
                if (Designation == "Team Member-DE")
                {
                    ViewBag.DEDashboard = "DataEntry TeamMember Dashboard!";
                    ViewBag.DETeamMemberDashboard = repoIDashboardDataEntry.GetDETeamMemberDEDashBoardInfo(teamMemerRowId, Designation);
                    //CreateNavigationforInsuffCaseForDE();
                }

                //DataEntry Team Member-DE-QC               
                if (Designation == "Team Member-DE-QC")
                {
                    ViewBag.DEDashboard = "DataEntry TeamMember QC Dashboard!";
                    ViewBag.DETeamMemberQCDashboard = repoIDashboardDataEntry.GetDETeamMemberDEQCDashBoardInfo(teamMemerRowId, Designation);
                    //CreateNavigationforInsuffCaseForDEQC();
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View();
        }

        #region ******* Manage Candidate *******

        [HttpGet]
        [SessionExpireFilterAttribute]
        [ValidateInput(false)]
        public ActionResult AddCandidate(int id = 0)
        {
            short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
            BindClientListBaseOnLogin(teamMemerRowId);

            dynamic expando = new ExpandoObject();
            var marksModel = expando as IDictionary<string, object>;

            BindTitleList();


            BindCandidateTypeList();
            int ClientRowID = id;

            ClientCustomize cc = new ClientCustomize();
            DataTable dt = new DataTable();
            dt = cc.Antecedents_select_form(ClientRowID, 0, "Data Entry", "Case");

            foreach (DataRow d in dt.Rows)
            {

                if (d[4].ToString() == "textbox")
                {
                    marksModel.Add(d[1].ToString(), "");
                }
                else if (d[4].ToString() == "dropdown")
                {
                    marksModel.Add(d[1].ToString() + "_" + d[2].ToString() + "_" + d[3].ToString(), d[0].ToString());
                }
                else if (d[4].ToString() == "checkbox")
                {
                    marksModel.Add(d[1].ToString() + "_" + d[2].ToString(), d[0].ToString());
                }
                else
                    marksModel.Add(d[1].ToString(), d[0].ToString());

            }


            ViewBag.clientRowId = ClientRowID.ToString();
            ClientCustomize bl = new ClientCustomize();
            ViewBag.LastFiveCases = repoPQPersonal.LastFiveClientCasesInitiated(0, teamMemerRowId);
            //return View(marksModel);
            return PartialView("AddCandidate", marksModel);
        }

