        public JsonResult GetClientBulkImport(short id = 0)
        {
            string templatte = "";
            if (id == 722)//Genpact
            {
                string FileName = "CandidateUploadTemplate_Genpact.xlsx";
                string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["clientCanidatetemplate"].ToString();
                templatte = Url.Content(FldPathDoc + FileName);



            }
            else if (id == 1057)//CTSIL UAN
            {
                string FileName = "CandidateUploadTemplate _CTSIL_UAN.xlsx";
                string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["clientCanidatetemplate"].ToString();
                templatte = Url.Content(FldPathDoc + FileName);
            }
            else if (id == 869)//IFFCO KISSAN
            {
                string FileName = "CandidateUploadTemplate_Iffcokissan.xlsx";
                string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["clientCanidatetemplate"].ToString();
                templatte = Url.Content(FldPathDoc + FileName);
            }
            else if (id == 272)//Walsons Services Private Limited (Security Services)
            {
                string FileName = "CandidateUploadTemplate_Walsons_272.xlsx";
                string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["clientCanidatetemplate"].ToString();
                templatte = Url.Content(FldPathDoc + FileName);
            }
            else
            {
                string FileName = "CandidateUploadTemplate.xlsx";
                string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["clientCanidatetemplate"].ToString();
                templatte = Url.Content(FldPathDoc + FileName);

            }
            return Json(templatte, JsonRequestBehavior.AllowGet);
        }
