        [NonAction]
        public string GatZipFileMessage(HttpPostedFileBase postedFile, string clientRowid, string filenm)
        {
            string NowTime = DateTime.Now.Hour.ToString() + DateTime.Now.Minute.ToString() + DateTime.Now.Second.ToString();
            GetMimeTypeTrue MimeType = new GetMimeTypeTrue();
            string ErrorMessage = "";
            string StartupPath = Server.MapPath("~/Uploads/TempFile/");
            StartupPath += clientRowid + "_" + filenm + "_" + NowTime;
            string TempPath = Server.MapPath("~/Uploads/");
            if (!Directory.Exists(StartupPath + "/"))
            {
                Directory.CreateDirectory(StartupPath);
            }
            ValidateParentFileUploadedByCandidate obj = new ValidateParentFileUploadedByCandidate();
            string ext = Path.GetExtension(postedFile.FileName);
            string filename = clientRowid + "_" + filenm + "_" + NowTime + ext;
            postedFile.SaveAs(TempPath + Path.GetFileName(filename));
            if (postedFile != null)
            {
                if (postedFile.ContentLength > 0)
                {
                    string[] AllowedExtension = new string[] { ".ZIP", ".zip" };
                    var bytes = System.IO.File.ReadAllBytes(TempPath + Path.GetFileName(filename));
                    if (MimeType.GetMimeType(bytes, TempPath + Path.GetFileName(filename)) == false)
                    {
                        ErrorMessage = "Only,.doc,.xls,.pdf,Image,MP3 and Zip File allowed";
                    }
                    else
                    {
                        if (!obj.IsValid(TempPath + Path.GetFileName(filename)))
                        {
                            ErrorMessage = obj.ErrorMessage;
                        }
                        if (ErrorMessage == "")
                        {
                            if (AllowedExtension.Contains(ext))
                            {
                                ZipFile.ExtractToDirectory(TempPath + Path.GetFileName(filename), StartupPath);
                                using (ZipArchive zipArchive = ZipFile.OpenRead(TempPath + Path.GetFileName(filename)))
                                {
                                    foreach (ZipArchiveEntry item in zipArchive.Entries)
                                    {
                                        ValidateChildFileUploadedByCandidate obj1 = new ValidateChildFileUploadedByCandidate();
                                        string[] Extension = item.Name.ToString().Split('.');
                                        string filePath = StartupPath + "/" + item.FullName;
                                        if (Extension.Length == 2 || Extension.Length == 3)
                                        {
                                            bytes = System.IO.File.ReadAllBytes(filePath);
                                            if (MimeType.GetMimeType(bytes, filePath) == false)
                                            {
                                                ErrorMessage = "Only,.doc,.pdf,Image,MP3 files allowed in Zip File ";
                                            }
                                            if (!obj1.IsValid(filePath))
                                            {
                                                ErrorMessage = obj1.ErrorMessage;
                                            }
                                        }

                                    }
                                }
                            }
                        }
                    }
                }
            }

            FileInfo file1 = new FileInfo(TempPath + Path.GetFileName(filename));
            if (file1.Exists)
            {
                file1.Delete();
            }
            if (Directory.Exists(StartupPath))
            {
                Directory.Delete(StartupPath, true);
            }
            return ErrorMessage;
        }



        [HttpPost]
        [SessionExpireFilterAttribute]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult UploadCandidateDocument(PQAddVerifiedUploadDocViewModel model, string UploadHid, IEnumerable<HttpPostedFileBase> UploadDoc)
        {
            try
            {
                if (ModelState.IsValid)
                {
                    string clid = "";

                    if (model.ClientRowId != "0")
                    {
                        if (int.TryParse(model.ClientRowId, out int result))
                        {
                            clid = model.ClientRowId;
                        }
                        else
                        {
                            clid = clsCommonMethods.PDecrypt(model.ClientRowId);
                        }

                    }

                    foreach (var item in UploadDoc)
                    {
                        string errorMessage = GatZipFileMessage(item, model.PersonalRowID.ToString(), model.CheckFamilyRowID.ToString());
                        if (errorMessage != "")
                        {
                            return RedirectToAction("UploadCandidateDocument", new { PID = clsCommonMethods.PEncrypt(model.PersonalRowID.ToString()), cId = clsCommonMethods.PEncrypt(model.CheckFamilyRowID.ToString()), sId = clsCommonMethods.PEncrypt(model.SubCheckRowID.ToString()), RfID = clsCommonMethods.PEncrypt(Session["SecuritasRefID"].ToString()), w = "", Msg = errorMessage });
                        }
                    }


                    if (model.NADoc == 1)
                    {
                        SavePQVerifiedUploadDoc(model.PersonalRowID, model.SubCheckRowID, "Provided", "NA", "provideddocuments", null, model.Remarks, model.NADoc);
                    }
                    else
                    {
                        if (model.PersonalRowID > 0 && !string.IsNullOrEmpty(UploadHid) && UploadDoc != null && UploadDoc.FirstOrDefault() != null)
                        {
                            int count = 0;
                            int cnt = 1;
                            ////string[] DocumentTypes = UploadHid.Split(',');
                            string[] DocumentTypesWithFile = model.CheckWithFileName.Split(',');
                            foreach (var item in UploadDoc)
                            {
                                string[] checkWithFile = DocumentTypesWithFile[count].Split('|');
                                model.DocumentType = checkWithFile[0];
                                model.FileName = checkWithFile[1];
                                cnt = Convert.ToInt32(checkWithFile[2]);
                                if (model.DocumentType != null && model.FileName != null && item.ContentLength > 0)
                                {
                                    if (model.DocumentType == "Others")
                                    {
                                        if (model.OtherDocName != null)
                                        {
                                            model.DocumentType = model.OtherDocName;
                                        }
                                    }
                                    SavePQVerifiedUploadDocMultiple(model.PersonalRowID, model.SubCheckRowID, "Provided", model.DocumentType, "provideddocuments", item, model.Remarks, model.NADoc, cnt.ToString());
                                    cc.CheckMovementProcessCompletionDate(Convert.ToInt32(model.PersonalRowID), model.SubCheckRowID, "DataEntry-Scanning");
                                }
                                else
                                {
                                    ViewBag.ErrorMsg = "No item found!";
                                    break;
                                }
                                count++;
                            }

                            #region Save LogTransaction Details
                            clsCommonMethods.AddPQLogTrasaction(model.PersonalRowID, "UploadCandidateDocument", "Provided", model.DocumentType, "Insert");
                            #endregion

                            #region Case/Check Action History Save 
                            clsCommonMethods.AddCheckActionHistory(model.PersonalRowID, model.SubCheckRowID, "Document Uploaded", "Document uploaded");
                            #endregion

                            int PID = model.PersonalRowID;
