        [HttpGet]
        public ActionResult BulkUploadCandidateDocs(string caseIds)
        {
            if (string.IsNullOrWhiteSpace(caseIds))
            {
                TempData["ErrorMsg"] = "No cases selected for bulk upload.";
                return RedirectToAction("ManageUploadDocmentList");
            }

            var ids = caseIds.Split(',')
                             .Where(x => int.TryParse(x, out _))
                             .Select(int.Parse)
                             .ToList();

            if (!ids.Any())
            {
                TempData["ErrorMsg"] = "Invalid case IDs.";
                return RedirectToAction("ManageUploadDocmentList");
            }

            var vm = new BulkUploadCandidateDocsViewModel
            {
                CaseIds = ids
            };

            return View(vm);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult UploadCandidateCaseDocumentBulk(BulkUploadCandidateDocsViewModel model)
        {
            try
            {
                if (model.CaseIds == null || !model.CaseIds.Any())
                {
                    ViewBag.ErrorMsg = "No cases selected for bulk upload.";
                    return View("BulkUploadCandidateDocs", model);
                }

                foreach (var caseId in model.CaseIds)
                {
                    ProcessSingleCaseUpload(caseId, model);
                }

                TempData["SuccessMsg"] = $"Documents uploaded for {model.CaseIds.Count} cases.";
                return RedirectToAction("AllocatedDEScannerBulkJob", new { CaseStatus = clsCommonMethods.PEncrypt("Pending"), version = clsCommonMethods.PEncrypt("New") });
            }
            catch (Exception ex)
            {
                ViewBag.ErrorMsg = ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), ex.Message, ex.StackTrace);
                return View("BulkUploadCandidateDocs", model);
            }
        }


        private void ProcessSingleCaseUpload(int personalRowId, BulkUploadCandidateDocsViewModel model)
        {
            DataTable dtPerInfo = cc.GetPersonalInfo(personalRowId);
            if (dtPerInfo.Rows.Count > 0)
            {
                var secRefId = dtPerInfo.Rows[0]["CompanyRefNo"].ToString();
                Session["SecuritasRefID"] = secRefId;
            }
            if (model.LOABool && model.LOADoc != null && model.LOADoc.ContentLength > 0)
            {
                string errorMessage = GatZipFileMessage(model.LOADoc, personalRowId.ToString(), "LetterOfAuthorization");
                if (errorMessage != "") throw new Exception(errorMessage);
                SavePQVerifiedUploadCaseDoc(personalRowId, "Provided", "Letter Of Authorization", "provideddocuments", model.LOADoc, model.Remarks);
            }

            if (model.CandidatePhotoBool && model.CandidatePhotoDoc != null && model.CandidatePhotoDoc.ContentLength > 0)
            {
                string errorMessage = GatZipFileMessage(model.CandidatePhotoDoc, personalRowId.ToString(), "CandidatePhoto");
                if (errorMessage != "") throw new Exception(errorMessage);
                SavePQVerifiedUploadCaseDoc(personalRowId, "Provided", "Candidate Photo", "provideddocuments", model.CandidatePhotoDoc, model.Remarks);
            }

            if (model.BGVPageBool && model.BGVPageDoc != null && model.BGVPageDoc.ContentLength > 0)
            {
                if (model.ClientRowId == 559 && (model.BGVPageDoc.FileName.ToUpper().Contains("ZIPX") || model.BGVPageDoc.FileName.ToUpper().Contains("ZIP") || model.BGVPageDoc.FileName.ToUpper().Contains("RAR")))
                    throw new Exception("Please do not upload ZIPX, ZIP, RAR file in BGV Page!");

                string errorMessage = GatZipFileMessage(model.BGVPageDoc, personalRowId.ToString(), "BGVPage");
                if (errorMessage != "") throw new Exception(errorMessage);
                SavePQVerifiedUploadCaseDoc(personalRowId, "Provided", "BGV Page", "provideddocuments", model.BGVPageDoc, model.Remarks);
            }

            if (model.BGVResumeBool && model.BGVResumeDoc != null && model.BGVResumeDoc.ContentLength > 0)
            {
                if (model.ClientRowId == 559 && (model.BGVResumeDoc.FileName.ToUpper().Contains("ZIPX") || model.BGVResumeDoc.FileName.ToUpper().Contains("ZIP") || model.BGVResumeDoc.FileName.ToUpper().Contains("RAR")))
                    throw new Exception("Please do not upload ZIPX, ZIP, RAR file in BGV Page!");

                string errorMessage = GatZipFileMessage(model.BGVResumeDoc, personalRowId.ToString(), "BGVResume");
                if (errorMessage != "") throw new Exception(errorMessage);
                SavePQVerifiedUploadCaseDoc(personalRowId, "Provided", "BGV Resume", "provideddocuments", model.BGVResumeDoc, model.Remarks);
            }

            if (model.OtherBool && model.OtherDoc != null && model.OtherDoc.ContentLength > 0)
            {
                string errorMessage = GatZipFileMessage(model.OtherDoc, personalRowId.ToString(), "OtherDocForCase");
                if (errorMessage != "") throw new Exception(errorMessage);
                SavePQVerifiedUploadCaseDoc(personalRowId, "Provided", "Other Doc For Case", "provideddocuments", model.OtherDoc, model.Remarks);
            }

            if (model.TechBool && model.Tech != null && model.Tech.ContentLength > 0)
            {
                string errorMessage = GatZipFileMessage(model.Tech, personalRowId.ToString(), "BGV EDU EMP Summary");
                if (errorMessage != "") throw new Exception(errorMessage);
                SavePQVerifiedUploadCaseDoc(personalRowId, "Provided", "BGV EDU EMP Summary", "provideddocuments", model.Tech, model.Remarks);
            }

            if (model.DocOtherBool && model.IdOtherDoc != null && model.IdOtherDoc.ContentLength > 0)
            {
                SavePQVerifiedUploadCaseDoc(model.PersonalRowID, "Provided", "Id Doc For Case", "provideddocuments", model.IdOtherDoc, model.Remarks);
                ClientCustomize clientCustomize = new ClientCustomize();
                DataTable dataTable = new DataTable();
                dataTable = cc.GetCheckIdForDocsUpload(model.PersonalRowID);
                string FolderNameForSave = "provideddocuments";
                string secRefId = Session["SecuritasRefID"].ToString();
                string DocumentType = "Id Doc For Case";
                string ext = Path.GetExtension(model.IdOtherDoc.FileName);
                foreach (DataRow dr in dataTable.Rows)
                {
                    int a = Convert.ToInt32(dr["SubCheckRowID"]);
                    string FldPathDoc = ConfigurationManager.AppSettings[FolderNameForSave.Trim().ToLower()].ToString();
                    string FileName = (secRefId + "_" + a + "_" + DocumentType).Replace(" ", "_").Replace("-", "_") + ext;
                    int res = cc.InsertToChecksSameAsCase(model.PersonalRowID, a, "Provided", DocumentType, FileName, FldPathDoc, model.Remarks, DateTime.Now);
                    model.IdOtherDoc.SaveAs(Server.MapPath(FldPathDoc + FileName));
                }
            }

            if (model.NABool)
            {
                SavePQVerifiedUploadCaseDoc(personalRowId, "Provided", "NA", "provideddocuments", null, model.Remarks, model.NABool);
            }

            // Log transaction and history
            clsCommonMethods.AddPQLogTrasaction(personalRowId, "UploadCandidateDocument", "Provided", model.DocumentType, "Insert");
            clsCommonMethods.AddCaseActionHistory(personalRowId, "BGV form or LOA document uploaded", "Case Document uploaded");
        }



        [HttpPost]
        [ValidateAntiForgeryToken]
        [SessionExpireFilterAttribute]

        public JsonResult CompletedDEScannerJobsBulk(string caseIds, int checkStatusId = 0, int subCheckId = 0)
        {
            var results = new List<BulkCaseResult>();

            try
            {
                // Parse IDs safely
                var idList = (caseIds ?? "")
                    .Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries)
                    .Select(s => int.TryParse(s.Trim(), out var id) ? id : 0)
                    .Where(id => id > 0)
                    .ToList();

                if (!idList.Any())
                {
                    return Json(new { success = false, message = "No valid case IDs provided.", results }, JsonRequestBehavior.AllowGet);
                }

                var teamMemberObj = Session["TeamMemberRowID"];
                if (teamMemberObj == null)
                {
                    return Json(new { success = false, message = "Session expired. Please sign in again.", results }, JsonRequestBehavior.AllowGet);
                }

                var teamMemberRowId = Convert.ToInt32(teamMemberObj);
                var cc = new ClientCustomize();

                foreach (var id in idList)
                {
                    try
                    {
                        // Log transaction
                        clsCommonMethods.AddPQLogTrasaction(id, "CompletedDEScannerJobs", "WIP", "Upload docs", "Upload document complete");

                        // Case action history
                        clsCommonMethods.AddCaseActionHistory(id, "WIP", "Scanner job completed");

                        // Update statuses
                        if (checkStatusId == 3)
                        {
                            cc.RejectedChecks_complete_FromDE(id, teamMemberRowId);
                        }
                        else
                        {
                            cc.UpdateCaseStatus(id, 7, teamMemberRowId);
                            var irStatus = UpdateInvestigationCaseStatus(id);
                            // You can log or use irStatus if needed
                        }

                        results.Add(new BulkCaseResult { CaseId = id, Success = true, Error = null });
                    }
                    catch (Exception caseEx)
                    {
                        // Log and record error per case
                        clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), caseEx.Message, caseEx.StackTrace);
                        results.Add(new BulkCaseResult { CaseId = id, Success = false, Error = caseEx.Message });
                    }
                }

                var successCount = results.Count(r => r.Success);
                var total = results.Count;
                var failed = total - successCount;

                return Json(new
                {
                    success = failed == 0, // consider overall success only if none failed
                    message = $"Processed {total} cases. Success: {successCount}, Failed: {failed}.",
                    results
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), ex.Message, ex.StackTrace);
                return Json(new { success = false, message = ex.Message, results }, JsonRequestBehavior.AllowGet);
            }
        }



