        [HttpPost]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult EnquiryEmail(ViewModels.VerificationViewModel.ReminderMail model)
        {
            try
            {
                if (model == null)
                {
                    ViewBag.ErrorMsg = "Invalid request.";
                    return View("~/Views/Shared/EnquiryEmail.cshtml", model);
                }

                if (string.IsNullOrWhiteSpace(model.Tomail))
                {
                    ViewBag.ErrorMsg = "To mail can not be blank.";
                    return View("~/Views/Shared/EnquiryEmail.cshtml", model);
                }

                if (string.IsNullOrWhiteSpace(model.subject))
                {
                    ViewBag.ErrorMsg = "Subject can not be blank.";
                    return View("~/Views/Shared/EnquiryEmail.cshtml", model);
                }

                if (string.IsNullOrWhiteSpace(model.Body))
                {
                    ViewBag.ErrorMsg = "Body can not be blank.";
                    return View("~/Views/Shared/EnquiryEmail.cshtml", model);
                }

                clsSendMail mail = new clsSendMail();

                string displayName = "Securitas India";

                //  Your system already uses this sender
                string fromEmail = "bgv.request@securitas-india.com";

                // Safe handling of null CC
                //string ccMail = string.IsNullOrWhiteSpace(model.ccmail) ? "" : model.ccmail;

                string fixedCC = "latika.gandhi@securitas-india.com;swarna.rasmi@securitas-india.com";

                string ccMail = string.IsNullOrWhiteSpace(model.ccmail)
                    ? fixedCC
                    : model.ccmail + ";" + fixedCC;

                bool result = mail.SendMail(
                    displayName,
                    fromEmail,
                    model.Tomail,
                    ccMail,
                    model.subject,
                    model.Body,
                    model.PersonalRowID   // optional tracking
                );

                //----------------------------------------------------

                if (result)
                {
                    ViewBag.SuccessMsg = "Mail Sent Successfully!";
                }
                else
                {
                    ViewBag.ErrorMsg = "Mail sending failed.";
                }
            }
            catch (Exception ex)
            {
                ViewBag.ErrorMsg = ex.Message;
            }

            return View("~/Views/Shared/EnquiryEmail.cshtml", model);
        }

