        [HttpGet]
        [SessionExpireFilterAttribute]
        [Route(Name = "DataEntry")]
        [ValidateInput(false)]
        public ActionResult AddEducationInfo(string ChFamilRowId = "", string sId = "", string window = "")
        {
            dynamic expando = new ExpandoObject();
            var marksModel = expando as IDictionary<string, object>;
            short ClientRowId = Convert.ToInt16(Session["ClientRowId"]);
            int PersonalRowID = Convert.ToInt32(Session["PersonalRowID"]);
            int SubCheckId = Convert.ToInt32(clsCommonMethods.PDecrypt(sId));
            int CheckFamilRowId = Convert.ToInt32(clsCommonMethods.PDecrypt(ChFamilRowId));
            ViewBag.UploadedDocInfo = repoPQVerifiedUploadDoc.GetCheckUploadDocList(PersonalRowID, Convert.ToInt16(SubCheckId));
            ViewBag.PersonalBind = repoPQPersonal.GetPersonalDetailsForTM(PersonalRowID, SubCheckId);
            Session["CheckFamilRowId"] = CheckFamilRowId;
            string Designaation = Session["Designation"].ToString();
            if (Designaation == "Team Leader-CS" || Designaation == "Manager-CS" || Designaation == "Team Member-CS")
            {
                ClientRowId = ViewBag.PersonalBind.ClientRowID;
            }
            ClientCustomize cc = new ClientCustomize();
            int tmid = Convert.ToInt32(Session["TeamMemberRowID"]);
            int desigid = Convert.ToInt32(Session["DesignationRowID"]);
            //int desigid = GetDesignationID(tmid);
            ViewBag.SpecialInstruction = GetSpecialInstructions(ClientRowId, Convert.ToInt16(CheckFamilRowId), desigid);

            ViewBag.CollgegIdn = cc.Antecedents_ResearchID(PersonalRowID, SubCheckId, "DETM");

            DataTable dt = new DataTable();
            dt = cc.Antecedents_client_select_form(ClientRowId, SubCheckId, "Data Entry", "Check");

            DataTable dbValue = new DataTable();
            dbValue = cc.Antecedents_client_select_DB(PersonalRowID, SubCheckId, "DETM");

            if (ClientRowId == 1324 || ClientRowId == 890)
            {
                GetCaseDocumentList(PersonalRowID, ClientRowId);
            }
            else
            {
                GetCaseDocumentList(PersonalRowID);
            }
            List<PQVerifiedUploadCaseDocViewModel> lst = new List<PQVerifiedUploadCaseDocViewModel>();
            lst = ViewBag.CaseDocList;
            lst = lst.Where(T => T.DocumentType == "Letter Of Authorization" || T.DocumentType == "Digital LOA" || T.DocumentType == "Uploaded By Client").ToList();
            lst = lst.Where(T => T.FileName != "").ToList();

            ViewBag.CaseDocList = lst;

            foreach (DataRow d in dt.Rows)
            {
                DataRow[] rowsFiltered = dbValue.Select("AntecedentRowID=" + d[0].ToString());
                if (rowsFiltered.Length > 0)
                {
                    if (d[4].ToString() == "textbox")
                    {
                        marksModel.Add(d[1].ToString(), rowsFiltered[0][1]);
                    }
                    else if (d[4].ToString() == "dropdown")
                    {
                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString() + "_" + d[3].ToString(), rowsFiltered[0][1].ToString());
                        if (d[1].ToString().Contains("72"))
                        {
                            ViewBag.degreeName = rowsFiltered[0][1].ToString();
                        }
                    }
                    else if (d[4].ToString() == "checkbox")
                    {
                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString(), rowsFiltered[0][1].ToString());
                    }
                    else if (d[4].ToString() == "fileUpload")
                        marksModel.Add(d[1].ToString(), d[0].ToString().ToString());

                }
                else
                {

                    if (d[4].ToString() == "textbox")
                    {
                        if (d[0].ToString() == "68")
                        {
                            DataTable dtperinfo = cc.GetPersonalInfo(PersonalRowID);
                            if (dtperinfo.Rows.Count > 0)
                            {
                                marksModel.Add(d[1].ToString(), dtperinfo.Rows[0]["CandidatefullName"]);
                            }
                        }
                        else if (d[0].ToString() == "185")
                        {
                            DataTable dtperinfo = cc.GetPersonalInfo(PersonalRowID);
                            if (dtperinfo.Rows.Count > 0)
                            {
                                marksModel.Add(d[1].ToString(), dtperinfo.Rows[0]["DOB"]);
                            }
                        }

                        else
                        {
                            marksModel.Add(d[1].ToString(), "");
                        }
                    }
                    else if (d[4].ToString() == "dropdown")
                    {
                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString() + "_" + d[3].ToString(), d[0].ToString());
                    }
                    else if (d[4].ToString() == "checkbox")
                    {
                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString(), d[0].ToString());
                    }
                    else
                        marksModel.Add(d[1].ToString(), d[0].ToString());
                }
            }

            int checkstatusid = cc.getCurrentCheckStatus(PersonalRowID, SubCheckId);
            ViewBag.PersonalRowid = PersonalRowID.ToString();
            ViewBag.SubCheckId = SubCheckId.ToString();
            ViewBag.clientRowId = ClientRowId.ToString();
            if (ViewBag.degreeName == null)
            {
                ViewBag.degreeName = "";

            }
            ViewBag.checkstatusid = checkstatusid.ToString();
            //GetEmploymentList();
            return View(marksModel);
        }

