                                        if (key == d[0].ToString())
                                        {
                                            //marksModel.Add(d[1].ToString(), formCollection[key].ToString());                            
                                            marksModel1.Add(d[1].ToString() + "_" + formCollection[key].ToString() + "_" + d[3].ToString(), d[0].ToString());



