            {
                Remarks = formCollection["INFRemarks"].ToString();
                int i = repoEducationResearch.SaveandUpdateInsuffRemark(PersonalRowid, SubCheckid, Remarks, DateTime.UtcNow.ToString(), "Raised");
            }
            var marksModel = expando as IDictionary<string, object>;
            try
            {
                CandidateDEModel cd = new CandidateDEModel();
                cd.PersonalRowID = PersonalRowid;
                cd.SubCheckRowID = SubCheckid;
                cd.clientRowId = clientRowid;
                cd.CreatedBy = Convert.ToInt32(Session["TeamMemberRowID"].ToString());
                cd.moduleName = "DETM";

                ViewBag.ErrorMsg = "";

                ClientCustomize bl = new ClientCustomize();
                DataTable dt = new DataTable();
                dt = bl.Antecedents_client_select_form(clientRowid, SubCheckid, "Data Entry", "Check");
                foreach (DataRow d in dt.Rows)
                {
                    string[] FString = d[1].ToString().Split('_');

                    foreach (string key in formCollection.AllKeys)
                    {
                        if (key == d[0].ToString())
                        {
                            cd.AntecedentRowID = Int64.Parse(d[0].ToString());
                            cd.DisplayName = FString[1].Trim();
                            cd.DataEntryValue = formCollection[key].ToString();
                            if (d[4].ToString() == "textbox")
                            {
                                if (FString[3].Trim().ToLower() == "mandatory" && cd.DataEntryValue == "")
                                {
                                    ViewBag.ErrorMsg = ViewBag.ErrorMsg + "<br>" + cd.DisplayName + " is a mandatory field";
                                }
                                if (cd.AntecedentRowID == 52) //Address
                                {
                                    int result = bl.ValidateDuplicateAddress(Convert.ToInt32(cd.PersonalRowID), Convert.ToInt32(cd.SubCheckRowID), 5, cd.DataEntryValue, "DETM");
                                    if (result == 1)
                                    {
                                        ViewBag.ErrorMsg = ViewBag.ErrorMsg + "<br>" + "Duplicate Address is found in Another Criminal check!";
                                    }
                                }
                                if (cd.AntecedentRowID == 60) //Tenure
                                {
                                    int result = bl.ValidateDuplicateAddress(Convert.ToInt32(cd.PersonalRowID), Convert.ToInt32(cd.SubCheckRowID), 5, cd.DataEntryValue, "DETM");
                                    if (result == 1)
                                    {
                                        ViewBag.ErrorMsg = ViewBag.ErrorMsg + "<br>" + "Duplicate Tenure is found in Another Criminal check!";
                                    }
                                }
                            }
                            if (d[4].ToString() == "dropdown")
                            {
                                if (FString[3].Trim().ToLower() == "mandatory" && cd.DataEntryValue == "--Select--")
                                {
                                    ViewBag.ErrorMsg = ViewBag.ErrorMsg + "<br>" + cd.DisplayName + " is a mandatory field";
                                }
                            }
                        }
                    }
                }

                foreach (DataRow d in dt.Rows)
                {
                    string[] FString = d[1].ToString().Split('_');

                    if (d[4].ToString() == "fileUpload")
                    {

                        foreach (string filenm in Request.Files)
                        {
                            if (filenm == d[0].ToString())
                            {
                                HttpPostedFileBase postedFile = Request.Files[filenm];
                                string path = Server.MapPath("~/Uploads/");
                                if (!Directory.Exists(path))
                                {
                                    Directory.CreateDirectory(path);
                                }
                                if (postedFile.ContentLength > 0)
                                {
                                    string filename = filenm + "_" + postedFile.FileName;
                                    postedFile.SaveAs(path + Path.GetFileName(filename));
                                    cd.AntecedentRowID = Int64.Parse(filenm);
                                    cd.DisplayName = FString[1];
                                    cd.DataEntryValue = filename;
                                    bl.tblDataEntry_Insert(cd);
                                }
                            }

                        }


                        foreach (string key in formCollection.AllKeys)
                        {
                            if (key == d[0].ToString())
                            {
                                marksModel.Add(d[1].ToString(), formCollection[key].ToString());
                            }
                        }
                    }


                    if (d[4].ToString() == "textbox")
                    {
                        foreach (string key in formCollection.AllKeys)
                        {
                            if (key == d[0].ToString())
                            {
                                marksModel.Add(d[1].ToString(), formCollection[key].ToString());
                                cd.AntecedentRowID = Int64.Parse(d[0].ToString());
                                cd.DisplayName = FString[1];
                                cd.DataEntryValue = Update_NA_NP(formCollection[key].ToString());
                                bl.tblDataEntry_Insert(cd);
                            }
                        }
                    }

                    else if (d[4].ToString() == "dropdown")
                    {
                        foreach (string key in formCollection.AllKeys)
                        {
                            if (key == d[0].ToString())
                            {
                                //marksModel.Add(d[1].ToString(), formCollection[key].ToString());                            
                                marksModel.Add(d[1].ToString() + "_" + formCollection[key].ToString() + "_" + d[3].ToString(), d[0].ToString());

                                cd.AntecedentRowID = Int64.Parse(d[0].ToString());
                                cd.DisplayName = FString[1];
                                cd.DataEntryValue = formCollection[key].ToString();
                                if (clientRowid == 268 && cd.AntecedentRowID == 377 && (cd.DataEntryValue == "--Select--"))
                                {
                                    throw new Exception("Please select value for 'Is current and permanent address same'.");
                                }
                                else
                                {
                                    bl.tblDataEntry_Insert(cd);
                                }

                            }
                        }
                    }

                    else if (d[4].ToString() == "checkbox")
                    {
                        int chkselect = 0;
                        foreach (string key in formCollection.AllKeys)
                        {
                            if (key == d[0].ToString())
                            {
                                marksModel.Add(d[1].ToString() + "_TRUE", d[0].ToString());
                                chkselect = 1;
                                cd.DataEntryValue = "TRUE";
                            }
                        }
                        if (chkselect == 0)
                        {
                            marksModel.Add(d[1].ToString() + "_FALSE", d[0].ToString());
                            cd.DataEntryValue = "FALSE";
                        }

                        cd.AntecedentRowID = Int64.Parse(d[0].ToString());
                        cd.DisplayName = FString[1];

                        bl.tblDataEntry_Insert(cd);
                    }

                    else
                        marksModel.Add(d[1].ToString(), d[0].ToString());

                }
                #region update Check status from dataentry 

                if (ViewBag.ErrorMsg == "")
                {
                    int checkstStatusID = 0;
                    if (Checkstatus == "Completed")
                    {
                        checkstStatusID = 14;
                        cc.CheckMovementProcessCompletionDate(Convert.ToInt32(cd.PersonalRowID), cd.SubCheckRowID, "DataEntry-TM");
                    }
                    else if (Checkstatus == "Insufficent")
                    {
                            checkstStatusID = 42;    
                            cc.Process_Remarks_Insert(Convert.ToInt32(cd.PersonalRowID), cd.SubCheckRowID, checkstStatusID, Remarks, "DataEntry-TM", cd.CreatedBy);
                    }

                    //else if (Checkstatus == "Research")
                    //    checkstStatusID = 12;
                    else if (Checkstatus == "Rejected")
                    {
                        checkstStatusID = 3;
                        cc.Process_Remarks_Insert(Convert.ToInt32(cd.PersonalRowID), cd.SubCheckRowID, checkstStatusID, Remarks, "DataEntry-TM", cd.CreatedBy);
                    }

                    else if (Checkstatus == "Review Requested")
                    {
                        checkstStatusID = 6;
                        cc.Process_Remarks_Insert(Convert.ToInt32(cd.PersonalRowID), cd.SubCheckRowID, checkstStatusID, Remarks, "DataEntry-TM", cd.CreatedBy);
                    }

                    else if (Checkstatus == "WIP-Pending")
                        checkstStatusID = 8;
                    else if (Checkstatus == "Not Applicable")
                    {
                        checkstStatusID = 37;
                        cc.UpdateStatusOfCheck(Convert.ToInt32(cd.PersonalRowID), cd.SubCheckRowID, 4, "", Convert.ToInt32(Session["TeamMemberRowID"].ToString()), "CheckNA");
                    }

                    if (checkstStatusID > 0)
                    {
                        cc.UpdateCheckStatus(Convert.ToInt32(cd.PersonalRowID), cd.SubCheckRowID, 1, checkstStatusID, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                        if (Checkstatus == "Completed")
                        {
                            if (checkstStatusID == 14)
                            {
                                if (SubmitWithQC == "SubmitWithQCApprove")
                                {
                                    formCollection["RejectionReason"] = "";

                                    UpdateCriminalInfo(formCollection, "Approve");
                                }
                            }
                        }

                    }
                    #region Case/Check Action History Save 

                    clsCommonMethods.AddCheckActionHistory(PersonalRowid, Convert.ToInt16(cd.SubCheckRowID), Checkstatus, Remarks);
                    #endregion
                    return RedirectToAction("ManageDataEntryJob", new { id = PersonalRowid, CheckstatusId = 8 });
                }
                #endregion





            }
            catch (Exception Ex)
            {
                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid parameter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                TempData["MessageRejection"] = Ex.Message;
                ViewBag.PersonalRowid = formCollection["PersonalRowid"].ToString();
                ViewBag.SubCheckId = formCollection["SubCheckId"].ToString();
                ViewBag.clientRowId = formCollection["clientRowId"].ToString();
                cc.Insert_LoginLog("AddCriminalInfo", Ex.Message, Convert.ToString(Session["TeamMemberRowID"]), " IP Address :" + GetIP_Address());

                return View(marksModel);
            }

            ViewBag.PersonalRowid = formCollection["PersonalRowid"].ToString();
            ViewBag.SubCheckId = formCollection["SubCheckId"].ToString();
            ViewBag.clientRowId = formCollection["clientRowId"].ToString();
            TempData["MessageRejection"] = "";

            return View(marksModel);
        }

        [HttpGet]
        [SessionExpireFilterAttribute]
        [Route(Name = "DataEntry")]
        public ActionResult ViewCriminalInfo(int id)
        {
            ViewCriminalViewModel model = new ViewCriminalViewModel();
            try
            {
                var Criminaldetails = repoCriminalInfo.GetCriminalInfoForQualityCheck(id);
                if (Criminaldetails == null)
                {
                    ViewBag.ErrorMsg = "No detail found!";
                    return View(model);
                }

                model.ClientRowID = Criminaldetails.ClientRowID;
                model.CheckFamilyRowID = Criminaldetails.CheckFamilyRowID;
                model.SubCheckRowID = Criminaldetails.SubCheckRowID;
                model.PersonalRowID = Criminaldetails.PersonalRowID;
                model.CriminalRowID = Criminaldetails.CriminalRowID;

                ViewBag.CriminalDetails = Criminaldetails;

                ViewBag.ListCriminal = repoDDL.GetAntecedentList(model.ClientRowID, model.CheckFamilyRowID, model.SubCheckRowID);
                model.UploadedDocInfo = repoPQVerifiedUploadDoc.GetCheckUploadDocList(model.PersonalRowID, model.SubCheckRowID);
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(model);
        }

        [HttpPost]
        [SessionExpireFilterAttribute]
        public ActionResult ViewCriminalInfo(string Approved, string Rejected, ViewCriminalViewModel model)
        {
            try
            {
                if (ModelState.IsValid)
                {
                    if (model != null && model.CriminalRowID > 0)
                    {
                        #region Update Criminal Information
                        if (!string.IsNullOrEmpty(model.Remarks))
                        {
                            model.CheckStatus = "WIP-Pending";

                            #region Save LogTransaction Details
                            clsCommonMethods.AddPQLogTrasaction(model.PersonalRowID, "ViewCriminalInfo", model.CheckStatus, "", "Update");
                            #endregion

                            #region Case/Check Action History Save 
                            clsCommonMethods.AddCheckActionHistory(model.PersonalRowID, model.SubCheckRowID, model.CheckStatus, model.Remarks);
                            #endregion

                            if (Session["Designation"].ToString() == "Team Leader-DE")
                            {
                                repoCriminalInfo.ViewCriminaInfoDETL(model);
                                TempData["SuccessMsg"] = "Record Update Successfully!";
                                ModelState.Clear();
                                return RedirectToAction("ManageReviewRequestedChecksForDETL", "Insuff");
                            }
                            if (Session["Designation"].ToString() == "Team Member-DE-QC")
                            {
                                if (Approved == "true")
                                {
                                    repoCriminalInfo.UpdateCriminalRejectionByDEQC(model, true);
                                }
                                else
                                {
                                    repoCriminalInfo.UpdateCriminalRejectionByDEQC(model);
                                }
                                TempData["SuccessMsg"] = "Record Update Successfully!";
                                ModelState.Clear();
                                return RedirectToAction("ManageRejectedChecksByDepTMForDEQC", "Insuff");
                            }
                        }
                        else
                        {
                            ModelState.AddModelError("", "Remark could not be blank!");
                        }
                        #endregion
                    }
                    else
                    {
                        ModelState.AddModelError("", "Invalid model!");
                    }
                }
                else
                {
                    var query = from state in ModelState.Values
                                from error in state.Errors
                                select error.ErrorMessage;

                    var errorList = query.ToList();
                    string strError = string.Empty;
                    foreach (string str in errorList)
                    {
                        strError += str + "\n";
                    }

                    ModelState.AddModelError("", strError);
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            ViewBag.ListCriminal = repoDDL.GetAntecedentList(model.ClientRowID, model.CheckFamilyRowID, model.SubCheckRowID);
            model.UploadedDocInfo = repoPQVerifiedUploadDoc.GetCheckUploadDocList(model.PersonalRowID, model.SubCheckRowID);
            return View(model);
        }

        #endregion

