        [HttpGet]
        [SessionExpireFilterAttribute]
        [Route(Name = "DataEntry")]
        [ValidateInput(false)]
        public ActionResult UpdateEmploymentInfo(string ChFamilRowId = "", string sId = "", string CRId = "", string Pid = "", string mas = "")
        {
            TempData["MessageRejection"] = "";
            if (mas != "")
            {
                TempData["MessageRejection"] = mas;
            }
            dynamic expando = new ExpandoObject();
            var marksModel = expando as IDictionary<string, object>;
            short ClientRowId = Convert.ToInt16(clsCommonMethods.PDecrypt(CRId));
            int PersonalRowID = Convert.ToInt32(clsCommonMethods.PDecrypt(Pid));
            short SubCheckId = Convert.ToInt16(clsCommonMethods.PDecrypt(sId));
            short CheckFamilRowId = Convert.ToInt16(clsCommonMethods.PDecrypt(ChFamilRowId));
            ClientCustomize cc = new ClientCustomize();
            ViewBag.UploadedDocInfo = repoPQVerifiedUploadDoc.GetCheckUploadDocList(PersonalRowID, SubCheckId);
            var PQPersonal = repoPQPersonal.GetPersonalDetailsForTM(PersonalRowID, SubCheckId);
            ViewBag.PersonalBind = PQPersonal;
            int tmid = Convert.ToInt32(Session["TeamMemberRowID"]);
            int desigid = GetDesignationID(tmid);
            ViewBag.SpecialInstruction = GetSpecialInstructions(ClientRowId, CheckFamilRowId, desigid);
            ViewBag.OrgID = cc.Antecedents_ResearchID(PersonalRowID, SubCheckId, "DETM");


            DataTable dt = new DataTable();
            dt = cc.Antecedents_client_select_form(ClientRowId, SubCheckId, "Data Entry", "Check");
            GetCheckActionHistories(PersonalRowID, SubCheckId);
            DataTable dbValue = new DataTable();
            dbValue = cc.GetDataEntryValue(PersonalRowID, SubCheckId);

            if (ClientRowId == 1324 || ClientRowId == 890)
            {
                GetCaseDocumentList(PersonalRowID, ClientRowId);
            }
            else
            {
                GetCaseDocumentList(PersonalRowID);
            }
            List<PQVerifiedUploadCaseDocViewModel> lst = new List<PQVerifiedUploadCaseDocViewModel>();
            lst = ViewBag.CaseDocList;
            lst = lst.Where(T => T.DocumentType == "Letter Of Authorization" || T.DocumentType == "Digital LOA" || T.DocumentType == "Uploaded By Client").ToList();
            lst = lst.Where(T => T.FileName != "").ToList();

            ViewBag.CaseDocList = lst;

            foreach (DataRow d in dt.Rows)
            {
                DataRow[] rowsFiltered = dbValue.Select("AntecedentRowID=" + d[0].ToString());
                if (rowsFiltered.Length > 0)
                {
                    if (d[4].ToString() == "textbox")
                    {
                        marksModel.Add(d[1].ToString(), rowsFiltered[0][1]);
                    }
                    else if (d[4].ToString() == "dropdown")
                    {
                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString() + "_" + d[3].ToString(), rowsFiltered[0][1].ToString());
                    }
                    else if (d[4].ToString() == "checkbox")
                    {
                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString(), rowsFiltered[0][1].ToString());
                    }
                    else if (d[4].ToString() == "fileUpload")
                        marksModel.Add(d[1].ToString(), d[0].ToString().ToString());

                }
                else
                {

                    if (d[4].ToString() == "textbox")
                    {
                        marksModel.Add(d[1].ToString(), "");
                    }
                    else if (d[4].ToString() == "dropdown")
                    {
                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString() + "_" + d[3].ToString(), d[0].ToString());
                    }
                    else if (d[4].ToString() == "checkbox")
                    {
                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString(), d[0].ToString());
                    }
                    else
                        marksModel.Add(d[1].ToString(), d[0].ToString());
                }
            }

            DataTable dtStatus = cc.getCheckStatus(PersonalRowID, SubCheckId);
            int CheckStatusID = Convert.ToInt32(dtStatus.Rows[0]["CheckStatusID"]);

            ViewBag.CheckComments = cc.GetProcessRemarksDE(PersonalRowID, SubCheckId, CheckStatusID);
            ViewBag.PersonalRowid = PersonalRowID.ToString();
            ViewBag.SubCheckId = SubCheckId.ToString();
            ViewBag.clientRowId = ClientRowId.ToString();

            TempData["Message"] = "";
            ViewBag.Name = PQPersonal.CandidateName.ToString();

            return View(marksModel);
        }

        [HttpPost]
        [SessionExpireFilterAttribute]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult UpdateEmploymentInfo(FormCollection formCollection, string action)
        {
            dynamic expando = new ExpandoObject();
            int PersonalRowid = Convert.ToInt32(formCollection["PersonalRowid"].ToString());
            short SubCheckid = Convert.ToInt16(formCollection["SubCheckId"].ToString());
            int clientRowid = Convert.ToInt32(formCollection["clientRowId"].ToString());
            bool isClientExclude = false;
            GetCheckActionHistories(PersonalRowid, SubCheckid);

            string Checkstatus = action;
            int result = 0;
            int CheckStatusId = 0;
            var marksModel = expando as IDictionary<string, object>;
            try
            {

                string bgvStatus = "";
                string CheckComments = (formCollection["RejectionReason"].ToString());
                ViewBag.CheckComments = CheckComments;
                if (clientRowid == 990)
                {
                    DataTable dts = new DataTable();
                    DataTable dtt = new DataTable();
                    string CheckStatusID = "";
                    string Remarks = "";
                    dtt = new API().Get_Check_Status_details(PersonalRowid, SubCheckid, bgvStatus.Trim(), CheckComments.Trim());
                    string checkFamilRowId = "";
                    if (dtt.Rows.Count > 0)
                    {
                        CheckStatusID = dtt.Rows[0]["CheckStatusID"].ToString();
                        checkFamilRowId = dtt.Rows[0]["CheckFamilyRowID"].ToString();
                        if (CheckStatusID == "42" || CheckStatusID == "53")
                        {
                            dts = new API().Get_Insuff_Remarks_details_Exist(PersonalRowid, SubCheckid, bgvStatus.Trim(), CheckComments.Trim());
                            if (dts.Rows.Count > 0)
                            {
                                new API().Insert_Insuff_Remarks_details(PersonalRowid, SubCheckid, bgvStatus.Trim(), CheckComments.Trim());
                                string CRId = clsCommonMethods.PEncrypt(clientRowid.ToString());
                                string Pid = clsCommonMethods.PEncrypt(PersonalRowid.ToString());
                                string sId = clsCommonMethods.PEncrypt(SubCheckid.ToString());
                                Remarks = "Rejection Reason Remarks already exits please change the remarks.";
                                string mas = "";
                                string ChFamilRowId = clsCommonMethods.PEncrypt(checkFamilRowId.ToString());
                                return RedirectToAction("UpdateEmploymentInfo", new { ChFamilRowId = ChFamilRowId, sId = sId, CRId = CRId, Pid = Pid, mas = Remarks });

                            }
                            else
                            {
                                new API().Insert_Insuff_Remarks_details(PersonalRowid, SubCheckid, bgvStatus.Trim(), CheckComments.Trim());
                            }
                        }
                    }

                }


                DataTable checkstatusDatatable = cc.getCheckStatus(PersonalRowid, SubCheckid);
                int CheckStatusIdNew = 0;
                if (checkstatusDatatable.Rows.Count > 0)
                {
                    CheckStatusIdNew = Convert.ToInt32(checkstatusDatatable.Rows[0][0].ToString());
                }

                DataTable dtPQP = new DataTable();
                dtPQP = cc.GetPersonalInfo(PersonalRowid);
                string CreatedBySource = string.Empty;
                if (dtPQP.Rows.Count > 0)
                {
                    CreatedBySource = Convert.ToString(dtPQP.Rows[0]["CreatedBySource"]);
                    if (Checkstatus != "Reject" && CreatedBySource.ToUpper().Trim() == "API" && (clientRowid == 327 || clientRowid == 317) && CheckStatusIdNew == 42)
                    {
                        DataTable dtm = new DataTable();
                        dtm = cc.ValidateCheckNotINDE(PersonalRowid, clientRowid);
                        if (dtm.Rows.Count > 0)
                        {
                            int flaging = Convert.ToInt32(dtm.Rows[0]["FlagRes"].ToString());
                            if (flaging == 1)
                            {
                                string CRId = clsCommonMethods.PEncrypt(clientRowid.ToString());
                                string Pid = clsCommonMethods.PEncrypt(PersonalRowid.ToString());
                                string sId = clsCommonMethods.PEncrypt(SubCheckid.ToString());
                                string Remarks = "L1 Insuff Cannot Raised Becuase Other check are On Data Entry Level";
                                string mas = "";
                                string ChFamilRowId = clsCommonMethods.PEncrypt(12.ToString());
                                return RedirectToAction("UpdateEmploymentInfo", new { ChFamilRowId = ChFamilRowId, sId = sId, CRId = CRId, Pid = Pid, mas = Remarks });
                            }
                        }
                    }
                }

                CandidateDEModel cd = new CandidateDEModel();
                cd.PersonalRowID = PersonalRowid;
                cd.SubCheckRowID = SubCheckid;
                cd.clientRowId = clientRowid;
                cd.CreatedBy = Convert.ToInt32(Session["TeamMemberRowID"].ToString());
                cd.moduleName = "DEQC";

                ClientCustomize bl = new ClientCustomize();
                DataTable dt = new DataTable();
                dt = bl.Antecedents_client_select_form(clientRowid, SubCheckid, "Data Entry", "Check");
                string remark = "";
                foreach (DataRow d in dt.Rows)
                {
                    string[] FString = d[1].ToString().Split('_');

                    if (d[4].ToString() == "fileUpload")
                    {

                        foreach (string filenm in Request.Files)
                        {
                            if (filenm == d[0].ToString())
                            {
                                HttpPostedFileBase postedFile = Request.Files[filenm];
                                string path = Server.MapPath("~/Uploads/");
                                if (!Directory.Exists(path))
                                {
                                    Directory.CreateDirectory(path);
                                }
                                if (postedFile.ContentLength > 0)
                                {
                                    string filename = filenm + "_" + postedFile.FileName;
                                    postedFile.SaveAs(path + Path.GetFileName(filename));
                                    cd.AntecedentRowID = Int64.Parse(filenm);
                                    cd.DisplayName = FString[1];
                                    cd.DataEntryValue = filename;
                                    result = bl.tblDataEntry_Insert(cd);
                                }
                            }

                        }


                        foreach (string key in formCollection.AllKeys)
                        {
                            if (key == d[0].ToString())
                            {
                                marksModel.Add(d[1].ToString(), formCollection[key].ToString());
                            }
                        }
                    }


                    if (d[4].ToString() == "textbox")
                    {
                        foreach (string key in formCollection.AllKeys)
                        {
                            if (key == d[0].ToString())
                            {
                                marksModel.Add(d[1].ToString(), formCollection[key].ToString());
                                cd.AntecedentRowID = Int64.Parse(d[0].ToString());
                                cd.DisplayName = FString[1];
                                cd.DataEntryValue = formCollection[key].ToString();
                                if (cd.DisplayName.ToUpper().Contains("REMARK"))
                                {
                                    remark = cd.DataEntryValue;
                                }
                                result = bl.tblDataEntry_Insert(cd);
