        [HttpPost]
        [SessionExpireFilterAttribute]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult ApproveEmploymentInfo(FormCollection formCollection)
        {
            try
            {
                // 1. Run Data Entry save logic (existing method)
                var deResult = AddEmploymentInfo(formCollection);



                // If Add returned validation error view, stop
                if (deResult is ViewResult)
                    return deResult;



                // 2. Run QC update logic (existing method)
                var qcResult = UpdateEmploymentInfo(formCollection, "Approve");



                // 3. Final redirect
                return RedirectToAction("ManageDataEntryJob",
         new { id = formCollection["PersonalRowid"], CheckstatusId = 8 });
            }
            catch (Exception ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), ex.Message, ex.StackTrace);
                ViewBag.ErrorMsg = "Approval failed due to error";
                return View();
            }
        }
