        public void SaveUANArtifectByMultiUAN(string AutoId, string MobileNo, int PersonalRowid, int CreatedBy, int SubCheckid)
        {
            try
            {
                if (AutoId != "")
                {

                    DataTable UANtbl = new DataTable();
                    UANtbl = cc.ExistsUANNOwithMobileNoaAndPan(Convert.ToInt32(AutoId), MobileNo, "", "", 1);

                    if (UANtbl.Rows.Count > 0)
                    {
                        string companyRefNo = "";
                        int J = 0;
                        for (J = 0; J < UANtbl.Rows.Count; J++)
                        {
                            var UANNO = UANtbl.Rows[J]["uan"].ToString();
                            AddUANCheckDetailsByAPI AddApiObj = new AddUANCheckDetailsByAPI();
                            string UAutoId = AddApiObj.AddUANDetailsLive(PersonalRowid, UANNO, CreatedBy);
                            if (UAutoId != "")
                            {
                                string body = string.Empty;
                                using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/UANCheck.html")))
                                {
                                    body = reader.ReadToEnd();
                                }
                                DataTable tbl = new DataTable();
                                tbl = cc.GetSprintVerify_epfoReport(Convert.ToInt32(UAutoId));

                                if (tbl.Rows.Count > 0)
                                {
                                    string name = "";
                                    string guardian_name = "";
                                    string uanNumberId = "";
                                    string data = "";
                                    int i = 0;
                                    for (i = 0; i < tbl.Rows.Count; i++)
                                    {
                                        string date_of_joining = "";
                                        string last_pf_submitted = "";
                                        if (i == 0)
                                        {
                                            companyRefNo = Convert.ToString(tbl.Rows[i]["companyRefNo"]);
                                            name = Convert.ToString(tbl.Rows[i]["name"]);
                                            guardian_name = Convert.ToString(tbl.Rows[i]["guardian_name"]);
                                            uanNumberId = Convert.ToString(tbl.Rows[i]["UANNO"]);
                                        }
                                        if (Convert.ToString(tbl.Rows[i]["date_of_joining"]) != "")
                                        {
                                            DateTime doj = Convert.ToDateTime(tbl.Rows[i]["date_of_joining"]);
                                            date_of_joining = doj.ToString("dd-MMM-yyyy");
                                        }
                                        if (Convert.ToString(tbl.Rows[i]["last_pf_submitted"]) != "")
                                        {
                                            DateTime doe = Convert.ToDateTime(tbl.Rows[i]["last_pf_submitted"]);
                                            last_pf_submitted = doe.ToString("MMM-yyyy");
                                        }
                                        data += "<tr>";
                                        data += "<td> " + Convert.ToString(tbl.Rows[i]["establishment_name"]) + " (" + Convert.ToString(tbl.Rows[i]["member_id"]) + ")" + " </td>";
                                        data += "<td> " + date_of_joining + " </td>";
                                        data += "<td> " + last_pf_submitted + " </td>";
                                        data += "</tr>";

                                    }
                                    body = body.Replace("{companyRefNo}", companyRefNo);
                                    body = body.Replace("{name}", name);
                                    body = body.Replace("{guardian_name}", guardian_name);
                                    body = body.Replace("{uanNumberId}", uanNumberId);
                                    body = body.Replace("{EstablishedDetails}", data);
                                    body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));

                                    //SavePQVerifiedUploadCaseUANDoc(PersonalRowid, "Provided", "UAN Report_"+ J.ToString(), "provideddocuments", body, "UAN No Verified", false, companyRefNo);
                                    SavePQVerifiedUploadUANDoc(PersonalRowid, Convert.ToInt16(SubCheckid), "Verified", "UAN Report_" + J.ToString(), "provideddocuments", body, "UAN No Verified from API", 0, companyRefNo);


                                }
                            }
                        }



                    }
                }

            }
            catch (Exception)
            {


            }

        }

