                                data += "<td> " + date_of_joining + " </td>";
                                data += "<td> " + date_of_exit + " </td>";
                                data += "</tr>";
                            }
                            uan_details += "<tr>";
                            uan_details += "<td colspan='3' style='color:#000; font-weight: bolder;'> " + Convert.ToString(tbl.Rows[i]["uan"]) + " </td>";
                            uan_details += "</tr>";

                            uan_details += "<tr>";
                            uan_details += "<td>Name</td>";
                            uan_details += "<td colspan='2'>" + Convert.ToString(tbl.Rows[i]["name"]) + "</td>";
                            uan_details += "</tr>";
                            uan_details += "<tr>";
                            uan_details += "<td>Gender</td>";
                            uan_details += "<td colspan='2'>" + Convert.ToString(tbl.Rows[i]["gender"]) + "</td>";
                            uan_details += "</tr>";
                            uan_details += "<tr>";
                            uan_details += "<td>Date Of Birth</td>";
                            uan_details += "<td colspan='2'>" + Convert.ToString(tbl.Rows[i]["date_of_birth"]) + "</td>";
                            uan_details += "</tr>";
                            uan_details += "<tr>";
                            uan_details += "<td>Employee Confidence Score</td>";
                            uan_details += "<td colspan='2'>" + Convert.ToString(tbl.Rows[i]["employee_confidence_score"]) + "</td>";
                            uan_details += "</tr>";
                            uan_details += "<tr>";
                            uan_details += "<td>Mobile</td>";
                            uan_details += "<td colspan='2'>" + Convert.ToString(tbl.Rows[i]["mobile"]) + "</td>";
                            uan_details += "</tr>";
                            uan_details += "<tr>";
                            uan_details += "<td>Aadhaar Verification Status</td>";
                            uan_details += "<td colspan='2'>" + Convert.ToString(tbl.Rows[i]["aadhaar_verification_status"]) + "</td>";
                            uan_details += "</tr>";
                            uan_details += "<tr>";
                            uan_details += "<td>Establishment Id</td>";
                            uan_details += "<td colspan='2'>" + Convert.ToString(tbl.Rows[i]["EstablishmentId"]) + "</td>";
                            uan_details += "</tr>";


                            uan_details += "<tr>";
                            uan_details += "<td style = 'color:#000; font-weight: bolder;'> Established Details </td>";
                            uan_details += "<td style = 'color:#000; font-weight: bolder;'> Date of joinning</td>";
                            uan_details += "<td style = 'color:#000; font-weight: bolder;'> Date Of Exit</td>";
                            uan_details += "</tr>";

                            uan_details += "<tr>";
                            uan_details += "<td> " + Convert.ToString(tbl.Rows[i]["EstablishmentName"]) + " (" + Convert.ToString(tbl.Rows[i]["MemberId"]) + ")" + " </td>";

                            if (Convert.ToString(tbl.Rows[i]["DateOfJoining"]) != "")
                            {
                                DateTime doj = Convert.ToDateTime(tbl.Rows[i]["DateOfJoining"]);
                                date_of_joining = doj.ToString("dd-MMM-yyyy");
                            }
                            if (Convert.ToString(tbl.Rows[i]["DateOfExit"]) != "")
                            {
                                DateTime doe = Convert.ToDateTime(tbl.Rows[i]["DateOfExit"]);
                                date_of_exit = doe.ToString("dd-MMM-yyyy");
                            }

                            uan_details += "<td> " + date_of_joining + " </td>";
                            uan_details += "<td> " + date_of_exit + " </td>";
                            uan_details += "</tr>";
                        }
                        body = body.Replace("{companyRefNo}", companyRefNo);
                        body = body.Replace("{member_id}", member_id);
                        body = body.Replace("{employer_confidence_score}", employer_confidence_score);
                        body = body.Replace("{matching_uan}", matching_uan);
                        body = body.Replace("{EstablishedDetails}", data);
                        body = body.Replace("{uan_details}", uan_details);
                        body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));

                        SavePQVerifiedUploadCaseUANDoc(PersonalRowid, "Verified", "UAN Case Report", "provideddocuments", body, "UAN No Verified", false, companyRefNo);

                    }
                }

            }
            catch (Exception)
            {


            }

        }



