        public bool ValidateCandidateName(string ProvidedName, string VerifiedName)
        {
            bool MatchStatus = false;
            try
            {
                if (ProvidedName.Trim().ToUpper() == VerifiedName.Trim().ToUpper())
                {
                    MatchStatus = true;
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return MatchStatus;
        }

        public bool ValidateCandidateDOB(string ProvidedDOB, string VerifiedDOB)
        {
            bool MatchStatus = false;
            try
            {
                DateTime dob = DateTime.ParseExact(VerifiedDOB, "yyyy-MM-dd", null);
                string formattedDob = dob.ToString("dd-MM-yyyy");
                if (ProvidedDOB.Trim().ToUpper() == formattedDob.Trim().ToUpper())
                {
                    MatchStatus = true;
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return MatchStatus;
        }

        public bool getPaysPrintDL(int PersonalRowid, int SubCheckid, int clientRowid, string IDNumber, string CandidateName, string DOB, string CheckUniqueID = "")
        {
            bool status = false;
            AddUANCheckDetailsByAPI AddApiObj = new AddUANCheckDetailsByAPI();
            try
            {
                string path = ConfigurationManager.AppSettings["CandidateLicenseImagePath"].ToString();
                string AutoId = AddApiObj.AddDrivingLicenseDetails(PersonalRowid, SubCheckid, clientRowid, IDNumber, CandidateName, Convert.ToInt32(Session["TeamMemberRowID"].ToString()), path, DOB, CheckUniqueID);
                if (AutoId != "")
                {
                    string body = string.Empty;
                    using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/DrivingLicense.html")))
                    {
                        body = reader.ReadToEnd();
                    }
                    DataTable tbl = new DataTable();
                    tbl = cc.GetDriving_License(Convert.ToInt32(AutoId), IDNumber, PersonalRowid);

                    if (tbl.Rows.Count > 0)
                    {
                        string companyRefNo = "";
                        string Full_Name = Convert.ToString(tbl.Rows[0]["name"]);
                        companyRefNo = Convert.ToString(tbl.Rows[0]["CompanyRefNo"]);
                        body = body.Replace("{companyRefNo}", companyRefNo);
                        body = body.Replace("{name}", Convert.ToString(tbl.Rows[0]["name"]));
                        body = body.Replace("{license_number}", Convert.ToString(tbl.Rows[0]["license_number"]));
                        body = body.Replace("{state}", Convert.ToString(tbl.Rows[0]["state"]));
                        body = body.Replace("{permanent_address}", Convert.ToString(tbl.Rows[0]["permanent_address"]));
                        body = body.Replace("{temporary_address}", Convert.ToString(tbl.Rows[0]["temporary_address"]));

                        body = body.Replace("{citizenship}", Convert.ToString(tbl.Rows[0]["citizenship"]));
                        body = body.Replace("{gender}", Convert.ToString(tbl.Rows[0]["gender"]));
                        body = body.Replace("{father_or_husband_name}", Convert.ToString(tbl.Rows[0]["father_or_husband_name"]));
                        body = body.Replace("{dob}", Convert.ToString(tbl.Rows[0]["dob"]));
                        body = body.Replace("{doe}", Convert.ToString(tbl.Rows[0]["doe"]));
                        body = body.Replace("{transport_doe}", Convert.ToString(tbl.Rows[0]["transport_doe"]));
                        body = body.Replace("{doi}", Convert.ToString(tbl.Rows[0]["doi"]));
                        body = body.Replace("{blood_group}", Convert.ToString(tbl.Rows[0]["blood_group"]));
                        body = body.Replace("{vehicle_classes}", Convert.ToString(tbl.Rows[0]["vehicle_classes"]));
                        body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));

                        body = body.Replace("{ImagePath}", Convert.ToString(tbl.Rows[0]["profile_image"]));

                        SavePQVerifiedUploadUANDoc(PersonalRowid, Convert.ToInt16(SubCheckid), "Verified", "Verification Artifact", "provideddocuments", body, "License Verified from API", 0, companyRefNo);
                        cc.UpdateTmMemberID(PersonalRowid, SubCheckid, "PaysPrint Pvt Ltd");
                        if (ValidateCandidateName(CandidateName, Full_Name))
                        {
                            var rst = cc.UpdateCandidateChecksReportComments(PersonalRowid, Convert.ToInt16(SubCheckid));
                            cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 36, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                            if (clientRowid == 735)
                            {
                                cc.UpdatePQCandidateChecksColorCode(654, 6, "No Risk", PersonalRowid, SubCheckid, "Exact Match Found");
                            }
                            else
                            {
                                cc.UpdatePQCandidateChecksColorCode(654, 6, "Green", PersonalRowid, SubCheckid, "Exact Match Found");
                            }
                            new API().UpdateAPICheckStatus(clientRowid.ToString().Trim(), PersonalRowid, SubCheckid, "CompletedbyOpsQC");  //APICheckStatus

                        }
                        else
                        {
                            cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 107, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                        }

                        clsCommonMethods.AddCheckActionHistory(PersonalRowid, Convert.ToInt16(SubCheckid), "Completed", "Verification recieve throught integration");
                        status = true;
                    }

                }
                return status;
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return status;
            }
