        public bool getPaysPrintPAN(int PersonalRowid, int SubCheckid, int clientRowid, string IDNumber, string CandidateName, string CheckUniqueID = "")
        {
            bool status = false;
            AddUANCheckDetailsByAPI AddApiObj = new AddUANCheckDetailsByAPI();
            try
            {
                string APIlog = Server.MapPath("~\\APILogs\\Logfiles");
                string AutoId = AddApiObj.AddPanNumberDetails(PersonalRowid, SubCheckid, clientRowid, IDNumber, Convert.ToInt32(Session["TeamMemberRowID"].ToString()), CheckUniqueID, APIlog);
                if (AutoId != "")
                {
                    string body = string.Empty;
                    using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/PANCardCheck.html")))
                    {
                        body = reader.ReadToEnd();
                    }
                    DataTable tbl = new DataTable();
                    tbl = cc.GetPAN(Convert.ToInt32(AutoId), IDNumber, PersonalRowid, SubCheckid);
                    if (tbl.Rows.Count > 0)
                    {
                        string companyRefNo = "";
                        string Full_Name = Convert.ToString(tbl.Rows[0]["full_name"]);
                        companyRefNo = Convert.ToString(tbl.Rows[0]["CompanyRefNo"]);
                        body = body.Replace("{CompanyRefNo}", companyRefNo);
                        body = body.Replace("{Name}", Convert.ToString(tbl.Rows[0]["full_name"]));
                        body = body.Replace("{PAN_Number}", Convert.ToString(tbl.Rows[0]["pan_number"]));
                        body = body.Replace("{VerifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));
                        body = body.Replace("{Member_Category}", Convert.ToString(tbl.Rows[0]["category"]));

                        SavePQVerifiedUploadUANDoc(PersonalRowid, Convert.ToInt16(SubCheckid), "Verified", "Verification Artifact", "provideddocuments", body, "PAN Card Verified from API", 0, companyRefNo);
                        cc.UpdateTmMemberID(PersonalRowid, SubCheckid, "PaysPrint Pvt Ltd");
                        if (ValidateCandidateName(CandidateName, Full_Name))
                        {
                            var rst = cc.UpdateCandidateChecksReportComments(PersonalRowid, Convert.ToInt16(SubCheckid));
                            cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 36, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                            if (clientRowid == 735)
                            {
                                cc.UpdatePQCandidateChecksColorCode(654, 6, "No Risk", PersonalRowid, SubCheckid, "Exact Match Found");
                            }
                            else
                            {
                                cc.UpdatePQCandidateChecksColorCode(654, 6, "Green", PersonalRowid, SubCheckid, "Exact Match Found");
                            }

                            new API().UpdateAPICheckStatus(clientRowid.ToString().Trim(), PersonalRowid, SubCheckid, "CompletedbyOpsQC");  //APICheckStatus
                        }
                        else
                        {
                            cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 107, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));

                        }
                        clsCommonMethods.AddCheckActionHistory(PersonalRowid, Convert.ToInt16(SubCheckid), "Completed", "Verification recieve throught integration");
                        status = true;
                    }

                }
                return status;
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return status;
            }
        }
        public bool GetPaysPrintAadhaar(int PersonalRowid, int SubCheckid, int clientRowid, string IDNumber, string CandidateName, string CheckUniqueID = "")
        {
            bool status = false;
            AddUANCheckDetailsByAPI AddApiObj = new AddUANCheckDetailsByAPI();
            try
            {

                string AutoId = AddApiObj.AddAadhaarNumberDetails(PersonalRowid, SubCheckid, clientRowid, IDNumber, CandidateName, Convert.ToInt32(Session["TeamMemberRowID"].ToString()), CheckUniqueID);

                if (AutoId != "")
                {
                    string body = string.Empty;
                    using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/AadhaarCard.html")))
                    {
                        body = reader.ReadToEnd();
                    }
                    DataTable tbl = new DataTable();

                    tbl = cc.GetAadhaar(Convert.ToInt32(AutoId), IDNumber, PersonalRowid, SubCheckid);
                    if (tbl.Rows.Count > 0)
                    {
                        string companyRefNo = "";

                        companyRefNo = Convert.ToString(tbl.Rows[0]["CompanyRefNo"]);
                        body = body.Replace("{companyRefNo}", companyRefNo);
                        body = body.Replace("{name}", CandidateName);
                        body = body.Replace("{aadhaar_number}", Convert.ToString(tbl.Rows[0]["aadhaar_number"]));
                        body = body.Replace("{age_range}", Convert.ToString(tbl.Rows[0]["age_range"]));
                        body = body.Replace("{state}", Convert.ToString(tbl.Rows[0]["state"]));
                        body = body.Replace("{gender}", Convert.ToString(tbl.Rows[0]["gender"]));

                        body = body.Replace("{last_digits}", Convert.ToString(tbl.Rows[0]["last_digits"]));
                        body = body.Replace("{is_mobile}", Convert.ToString(tbl.Rows[0]["is_mobile"]));
                        body = body.Replace("{remarks}", Convert.ToString(tbl.Rows[0]["remarks"]));
                        body = body.Replace("{less_info}", Convert.ToString(tbl.Rows[0]["less_info"]));
                        body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));

                        SavePQVerifiedUploadUANDoc(PersonalRowid, Convert.ToInt16(SubCheckid), "Verified", "Verification Artifact", "provideddocuments", body, "Aadhaar Verified form API", 0, companyRefNo);
                        cc.UpdateTmMemberID(PersonalRowid, SubCheckid, "PaysPrint Pvt Ltd");
                        var rst = cc.UpdateCandidateChecksReportComments(PersonalRowid, Convert.ToInt16(SubCheckid));
                        cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 36, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                        if (clientRowid == 735)
                        {
                            cc.UpdatePQCandidateChecksColorCode(654, 6, "No Risk", PersonalRowid, SubCheckid, "Verified");
                        }
                        else
                        {
                            cc.UpdatePQCandidateChecksColorCode(654, 6, "Green", PersonalRowid, SubCheckid, "Verified");
                        }
                        new API().UpdateAPICheckStatus(clientRowid.ToString().Trim(), PersonalRowid, SubCheckid, "CompletedbyOpsQC");  //APICheckStatus
                        status = true;
                    }

                }
                return status;
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);

                return status;
            }

        }


