                {
                    CreatedBySource = Convert.ToString(dtPQP.Rows[0]["CreatedBySource"]);
                    if (Checkstatus != "Reject" && CreatedBySource.ToUpper().Trim() == "API" && (clientRowid == 327 || clientRowid == 317) && CheckStatusIdNew == 42)
                    {
                        DataTable dtm = new DataTable();
                        dtm = cc.ValidateCheckNotINDE(PersonalRowid, clientRowid);
                        if (dtm.Rows.Count > 0)
                        {
                            int flaging = Convert.ToInt32(dtm.Rows[0]["FlagRes"].ToString());
                            if (flaging == 1)
                            {
                                string CRId = clsCommonMethods.PEncrypt(clientRowid.ToString());
                                string Pid = clsCommonMethods.PEncrypt(PersonalRowid.ToString());
                                string sId = clsCommonMethods.PEncrypt(SubCheckid.ToString());
