        public bool getPanToGstArtifact(int PersonalRowId, int ClientRowId, int SubCheckRowId, string PanNo, string CompanyRefNo)
        {
            bool status = false;
            try
            {
                string ArtifactPath = Server.MapPath("~/Emailers/DIgiTapGstCheck.html");
                string apiLogs = Server.MapPath(@"~\APILogs\Logfiles");
                AddUANCheckDetailsByAPI APIobj = new AddUANCheckDetailsByAPI();
                DataBaseConnections DC = new DataBaseConnections();
                ClientCustomize CC = new ClientCustomize(); 
                string body = APIobj.getPanToGst(PersonalRowId, SubCheckRowId,CompanyRefNo, PanNo, ArtifactPath, apiLogs);
                if (Convert.ToString(body) != "")
                { 
                    var DT = DC.GetDigiTapPanToGst(0, PersonalRowId, SubCheckRowId, CompanyRefNo, PanNo, "", "");
                    
                if (DT.Rows.Count > 0)
                    {
                        string JsonString = Convert.ToString(DT.Rows[0]["JsonString"]);

                        var model = JsonConvert.DeserializeObject<gstRoot>(JsonString);
                        if (model.http_status_code == 200)
                        {   
                            int teamMemberId = Session["TeamMemberRowID"] != null ? Convert.ToInt32(Session["TeamMemberRowID"]) : 0;
                            if (model.result_code == 101)
                            {
                                DataTable dt = new DataTable();

                                dt = CC.Antecedents_client_select_form(ClientRowId, SubCheckRowId, "Operation", "Check");
                                if (dt.Rows.Count > 0)
                                {
                                    for (int i = 0; i < dt.Rows.Count; i++)
                                    {
                                        int Antecedents = Convert.ToInt32(dt.Rows[i]["AntecedentsRowID"]);
                                        int AutoId = DC.InsertUpdateGSTCheckDetails(PersonalRowId, SubCheckRowId, Antecedents, "YES");
                                    }
                                }
                                string File_name = SavePQVerifiedUploadUAN_Doc(PersonalRowId, Convert.ToInt16(SubCheckRowId), "Verified", "Verification Artifact", "provideddocuments", body, "GST Verified from API", 0, CompanyRefNo);
                                cc.UpdateCheckStatus(PersonalRowId, SubCheckRowId, 1, 115, "Check", teamMemberId);
                                status = true;
                            }
                            else if (model.result_code == 103 || model.result_code == 108)
                            {
                                DataTable dt = new DataTable();
                                dt = CC.Antecedents_client_select_form(ClientRowId, SubCheckRowId, "Operation", "Check");
                                if (dt.Rows.Count > 0)
                                {
                                    for (int i = 0; i < dt.Rows.Count; i++)
                                    {
                                        int Antecedents = Convert.ToInt32(dt.Rows[i]["AntecedentsRowID"]);
                                        int AutoId = DC.InsertUpdateGSTCheckDetails(PersonalRowId, SubCheckRowId, Antecedents, "NO");
                                    }
                                }
                                string File_name = SavePQVerifiedUploadUAN_Doc(PersonalRowId, Convert.ToInt16(SubCheckRowId), "Verified", "Verification Artifact", "provideddocuments", body, "GST Verified from API", 0, CompanyRefNo);
                                cc.UpdateCheckStatus(PersonalRowId, SubCheckRowId, 1, 36, "Check", teamMemberId);

                                if (ClientRowId == 735)
                                {
                                    cc.UpdatePQCandidateChecksColorCode(654, 6, "No Risk", PersonalRowId, SubCheckRowId, "No Record Found");
                                }
                                else
                                {
                                    cc.UpdatePQCandidateChecksColorCode(654, 6, "Green", PersonalRowId, SubCheckRowId, "No Record Found");
                                }

                                new API().UpdateAPICheckStatus(ClientRowId.ToString().Trim(), PersonalRowId, SubCheckRowId, "CompletedbyOpsQC");  //APICheckStatus


                                status = true;
                            }
                            cc.UpdateTmMemberID(PersonalRowId, SubCheckRowId, "Digitap");

                            clsCommonMethods.AddCheckActionHistory(PersonalRowId, Convert.ToInt16(SubCheckRowId), "Completed", "Verification received through API");
                        }
                    }

                }
            }
            catch (Exception Ex)
            {
               
            }
            return status;

        }
        public bool getDinToPan(int PersonalRowId,int ClientRowId,int SubCheckRowId,string PanNo,string CompanyRefNo)
        {
            bool status = false;
            try
            {
                string ArtifactPath = Server.MapPath("~/Emailers/llmtechDINCheck.html");
