        public bool DobValidate(int PersonalRowid, int SubCheckid)
        {
            bool Status = true;
            try
            {
                ClientCustomize bl = new ClientCustomize();
                var Databasetbl = bl.GetCandidateDatabaseCheckDetails(PersonalRowid, SubCheckid);
                if (Databasetbl.Rows.Count > 0)
                {
                    string DOB = Convert.ToString(Databasetbl.Rows[0]["DOB"]);
                    var DOB_ = DOB.Split('-');
                    string Month = getMonth(DOB_[1]);
                    string DoB = DOB_[0] + "-" + Month + "-" + DOB_[2];
                    DateTime givenDate = DateTime.ParseExact(DoB, "dd-MMM-yyyy", CultureInfo.InvariantCulture);
                    DateTime today = DateTime.Today;
                    int years = today.Year - givenDate.Year;
                    if (years < 18)
                    {
                        Status = false;
                    }
                }
            }
            catch (Exception Ex)
            {
            }
            return Status;
        }
        public bool CIBILartifactUploadfromAPI(int pId, int sId, int cId, string RefNo)
        {
            bool status = false;

            try
            {
                DataBaseConnections conObj = new DataBaseConnections();
                var API = new AddUANCheckDetailsByAPI();

                DataTable spDT = conObj.GetSepcialCheckDataFromtblDataEntry(pId, sId);
                if (spDT != null && spDT.Rows.Count > 0)
                {
                    var row = spDT.Rows[0];
                    string name = Convert.ToString(row["CandidateName"]);
                    string mobileNo = Convert.ToString(row["MobileNo"]);
                    string panNo = Convert.ToString(row["PanNo"]);
                    if (name != "" && mobileNo != "" && panNo != "")
                    {
                        string apiLogs = Server.MapPath(@"~\APILogs\Logfiles");
                        string fldPathDoc = Server.MapPath(ConfigurationManager.AppSettings["provideddocuments"]);

                        var statusResponse = API.CIBILReportWithScore(pId, sId, panNo, name, mobileNo, RefNo, apiLogs, fldPathDoc);

                        int teamMemberId = Session["TeamMemberRowID"] != null ? Convert.ToInt32(Session["TeamMemberRowID"]) : 0;
                        if (statusResponse.Status == "Success")
                        {
                            DataTable dt = cc.Antecedents_client_select_form(cId, sId, "Operation", "Check");
                            if (dt != null && dt.Rows.Count > 0)
                            {
                                foreach (DataRow dr in dt.Rows)
                                {
                                    int antecedents = Convert.ToInt32(dr["AntecedentsRowID"]);
                                    cc.InsertUpdateCibilCheckDetails(pId, sId, antecedents, statusResponse.credit_score);
                                }
                            }
                            conObj.AddCIBILDetails(pId, sId, RefNo, panNo, name, mobileNo, 200, statusResponse.FileName, statusResponse.credit_score);
                            SavePQVerifiedUploadDocCibil(pId, Convert.ToInt16(sId), "Verified", "Verification Artifact", "provideddocuments", statusResponse.FileName, "CIBIL Verified from API");
                            cc.UpdateCheckStatus(pId, sId, 1, 107, "Check", teamMemberId);
                            clsCommonMethods.AddCheckActionHistory(pId, Convert.ToInt16(sId), "Completed", "Verification received through API");
                            status = true;
                            cc.UpdateTmMemberID(pId, sId, "Llmtech");
                        }
                        else
                        {
                            cc.UpdateCheckStatus(pId, sId, 1, 16, "Check", teamMemberId);
                            conObj.AddCIBILDetails(pId, sId, RefNo, panNo, name, mobileNo, 400, "","");
                        }

                    }

                }
            }
