        public bool UANartifactwithvalidationOld(int Pid, int Sid, int Cid, string UanNo, string RefNo)
        {
            bool status = false;
            DataBaseConnections DC = new DataBaseConnections();
            try
            {
                var model = getDigiTapUANWithOutStatusUpdate(Pid, Sid, UanNo, Cid, RefNo);
                if (model != null)
                {
                    if (model?.EmploymentHistory != null && model.EmploymentHistory.Count > 0)
                    {
                        // Identify WALSONS employment record
                        var walsons = model.EmploymentHistory
                            .FirstOrDefault(r => r.establishment_name.ToUpper().Contains("WALSONS SERVICES"));
                        if (walsons == null)
                        {
                            // Handle case where WALSONS record is not found
                            status = true; // or false depending on your business rule
                            DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "No WALSONS SERVICES record found in UAN report – cannot apply Walsons-specific checks", "Success");

                            if (status == true && model.EmploymentHistory.Count == 1)
                            {
                                DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid,
                                    "Verified clear – no observations", "Success");
                            }
                        }
                        else
                        {
                            foreach (var emp in model.EmploymentHistory)
                            {
                                if (emp == walsons) continue;

                                string date_of_exit = emp.date_of_exit;
                                string date_of_joining = emp.date_of_joining;

                                // Case: Last working day not updated
                                if (string.IsNullOrEmpty(date_of_exit))
                                {
                                    if (emp.establishment_name.ToUpper().Contains("WALSONS SERVICES"))
                                    {
                                        status = true;
                                        DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Last Working Day not updated on UAN report but no overlapping – hence clear", "Success");
                                    }
                                    else
                                    {
                                        status = true;
                                        DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Last Working Day not updated on UAN report for previous employment, but clear", "Success");
                                    }
                                    continue;
                                }

                                DateTime prevExit = Convert.ToDateTime(emp.date_of_exit);
                                DateTime prevJoin = Convert.ToDateTime(emp.date_of_joining);
                                DateTime walsonsJoin = Convert.ToDateTime(walsons.date_of_joining);

                                // Green Category checks
                                double daysDiff = (walsonsJoin - prevExit).TotalDays;
                                if (daysDiff >= 0 && daysDiff < 60)
                                {
                                    status = true;
                                    DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Overlapping with previous employment less than 60 days before joining Walson’s – considered Green", "Success");
                                }
                                else if (daysDiff >= 60)
                                {
                                    status = true;
                                    DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Overlapping with previous employment more than 60 days before joining Walson’s – considered Green", "Success");
                                }

                                if (walsonsJoin < prevExit)
                                {
                                    status = true;
                                    DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Dual employment found with previous employment before joining Walson’s – considered Green", "Success");
                                }

                                // Red Category checks
                                if (prevJoin >= walsonsJoin)
                                {
                                    status = false;
                                    DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Another employer name appears on UAN after joining Walson’s – Red", "Exception");

                                    double concurrentDays = (prevJoin - walsonsJoin).TotalDays;
                                    if (concurrentDays < 60)
                                    {
                                        status = false;
                                        DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Overlapping with Walson’s for less than 60 days – concurrent employment – Red", "Exception");
                                    }
                                    else
                                    {
                                        status = false;
                                        DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Overlapping with Walson’s for more than 60 days – concurrent employment – Red", "Exception");

                                    }
                                    return status;
                                }
                            }
                            // If no issues found at all
                            if (status == true && model.EmploymentHistory.Count == 1)
                            {
                                DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Verified clear – no observations", "Success");
                            }
                        }
                    }
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                throw;
            }
            return status;
        }

        public int UANartifactwithvalidation(int Pid, int Sid, int Cid, string UanNo, string RefNo)
        {
            int status = 0;
            DataBaseConnections DC = new DataBaseConnections();
            try
            {
                // Rule: Incorrect UAN → RED
                if (string.IsNullOrEmpty(UanNo) || UanNo.Length < 12)
                {
                    status = 0;
                    DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Incorrect UAN Number – RED", "Exception");
                    return status;
                }

                var model = getDigiTapUANWithOutStatusUpdate(Pid, Sid, UanNo, Cid, RefNo);
                if (model != null && model.EmploymentHistory != null && model.EmploymentHistory.Count > 0)
                {
                    var walsons = model.EmploymentHistory
                        .FirstOrDefault(r => r.establishment_name.ToUpper().Contains("WALSONS SERVICES"));

                    if (walsons == null)
                    {
                        status = 1;
                        DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Verified Clear, No observation – Green", "Success");
                    }
                    else
                    {
                        DateTime walsonsJoinDate = Convert.ToDateTime(walsons.date_of_joining);
                        DateTime? walsonsdate_of_exit = null;
                        if (!string.IsNullOrEmpty(walsons.date_of_exit))
                        {
                            walsonsdate_of_exit = Convert.ToDateTime(walsons.date_of_exit);
                        }

                        foreach (var emp in model.EmploymentHistory)
                        {
                            if (emp == walsons) continue;

                            string date_of_exit = emp.date_of_exit;
                            DateTime prevJoin = Convert.ToDateTime(emp.date_of_joining);

                            // RULE 1: Walsons exit not updated + later employment → RED
                            if (string.IsNullOrEmpty(walsons.date_of_exit) && prevJoin > walsonsJoinDate)
                            {
                                status = 0;
                                DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid,
                                    "Walsons exit date not updated, but subsequent employment found – RED", "Exception");
                                return status;
                            }


                            // RULE 2: Another employer appears after Walsons → RED
                            if (string.IsNullOrEmpty(walsons.date_of_exit) && prevJoin > walsonsJoinDate)
                            {
                                status = 0;
                                double concurrentDays = (prevJoin - walsonsJoinDate).TotalDays;
                                if (concurrentDays < 60)
                                {
                                    DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid,
                                        "Overlapping with Walsons less than 60 days – RED", "Exception");
                                }
                                else
                                {
                                    DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid,
                                        "Overlapping with Walsons more than 60 days – RED", "Exception");
                                }
                                return status;
                            }
                            if (!string.IsNullOrEmpty(walsons.date_of_exit))
                            {
                                DateTime walsonsExitDate = Convert.ToDateTime(walsons.date_of_exit);
                                if (prevJoin < walsonsExitDate)
                                {
                                    status = 0;
                                    DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid,
                                    "Dual Employment found after joining Walsons – RED", "Exception");
                                    return status;
                                }
                                if (prevJoin > walsonsExitDate)
                                {
                                    status = 0;
                                    DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid,
                                    "Another employer name appearing after Walsons - RED", "Exception");
                                    return status;
                                }
                            }

                            // Case: Last working day not updated for other employers → Green
                            if (string.IsNullOrEmpty(date_of_exit))
                            {
                                status = 1;
                                DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid,
                                    "Last working day not updated on UAN report but no overlapping – Green", "Success");
                                continue;
                            }

                            DateTime prevExit = Convert.ToDateTime(emp.date_of_exit);

                            // Green Category checks
                            double daysDiff = (walsonsJoinDate - prevExit).TotalDays;
                            if (daysDiff >= 0 && daysDiff < 60)
                            {
                                status = 1;
                                DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid,
                                    "Overlapping with previous employment less than 60 days before Walsons – Green", "Success");
                            }
                            else if (daysDiff >= 60)
                            {
                                status = 1;
                                DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid,
                                    "Overlapping with previous employment more than 60 days before Walsons – Green", "Success");
                            }

                            if (walsonsJoinDate < prevExit)
                            {
                                status = 1;
                                DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid,
                                    "Dual employment found with previous employment before joining Walsons – Green", "Success");
                            }
                        }

                        // If only Walsons record exists and no issues
                        if (status == 1 && model.EmploymentHistory.Count == 1)
                        {
                            DC.AddUANCheckToBGVFormCheckStatus(Pid, Sid, "Verified Clear, No observation – Green", "Success");

                        }
                    }
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return 2;
            }
            return status;
        }

