                personalData.CandidateIncludeInInsuffMail = 0;
            }

            //if ((personalData.PackageName != "Package-FAIPL_Comprehensive" || personalData.PackageName != "Package-FAIPL_Comprehensive Package + Additional Check" || personalData.PackageName != "Package-FAIPL_Package Fresher Hires (CRCP_ID_PADD_GDB_EDU_OFAC)"|| personalData.PackageName == "Package-FAIPL_Interim Package" || personalData.PackageName == "Package-FAIPL_Comprehensive Package + Drug Test Panel 9"|| personalData.PackageName == "FAIPL_Comprehensive Package + Credit Check") && ClientRowID == 559)
