                }

                var data = Model1.Where(x => x.Name.Trim() == Name.Trim() && x.Mobile.Trim() == Mobile.Trim()).FirstOrDefault();
                cc.AddBulkUpload_CRC_Id_Address(data);
            }
        }

        private static bool IsValidEmail(string email)
        {
            try
            {
                var r = new Regex(@"^([0-9a-zA-Z]([-\.\w]*[0-9a-zA-Z])*@([0-9a-zA-Z][-\w]*[0-9a-zA-Z]\.)+[a-zA-Z]{2,9})$");

                return !string.IsNullOrEmpty(email) && r.IsMatch(email);
            }
            catch (Exception)
            {
                throw;
            }
        }

        public JsonResult GetChecksAndPackageByClientId(short cid = 0, byte pt = 0)
        {
            try
            {
                //Package" = "1"    Check"   = "2"   Both"    = "3"  
                if (cid > 0)
                {
                    var data = repoPQClient.GetChecksAndPackageByClientId(cid, pt);
                    return Json(data, JsonRequestBehavior.AllowGet);
                }
                else
                {
                    return Json(0, JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception)
            {
                throw;
            }
        }

