        //Save Package Or Check for Candidate
        void SavePackageOrCheckWithCandidate(AddPQPersonalViewModel model)
        {
            try
            {
                ClientCustomize cc = new ClientCustomize();
                AddPQCandidateCheckViewModel chekModel = new AddPQCandidateCheckViewModel();
                chekModel.ClientRowID = model.ClientRowID;
                chekModel.PersonalRowID = model.PersonalRowID;
                string[] strChkPkg = model.CandidateCheckOrPackage.Split(',');
                foreach (var ChkPkg in strChkPkg)
                {
                    string[] strIds = ChkPkg.Split('-');
                    if (!string.IsNullOrEmpty(strIds[0]))
                    {
                        if (strIds[0] == "Check")
                        {
                            int ClientCheckRowID = Convert.ToInt32(strIds[1]);
                            var ChekData = repoClientCheck.GetChecksByClientId(model.ClientRowID).Where(p => p.ClientCheckRowID == ClientCheckRowID && p.AntecedentSelected == 1);
                            chekModel.ClientPackageRowID = 0;
                            foreach (var item in ChekData)
                            {
                                //chekModel.ClientCheckRowID = item.ClientCheckRowID;
                                //repoPQCandidateCheck.AddCandidateCheck(chekModel);
                                //repoPQCandidateCheck.SaveChanges();
                                cc.CandidateCheckMoveToPQCandidate(chekModel.ClientRowID, chekModel.PersonalRowID, chekModel.ClientPackageRowID, item.ClientCheckRowID); //item.SubCheckRowID is subCheckFamilyID
                                if (item.CheckFamilyRowID == 5 && chekModel.ClientRowID == 249)
                                {
                                    new API().UpdateAPINewCaseInitiateStatus(chekModel.PersonalRowID, chekModel.ClientRowID.ToString(), "AddCaseCRC");
                                }
                                else
                                {
                                    new API().UpdateAPINewCaseInitiateStatus(chekModel.PersonalRowID, chekModel.ClientRowID.ToString(), "AddCase");
                                }
                            }
                        }
                        if (strIds[0] == "Package")
                        {
                            string pkgnm = ChkPkg.Replace(strIds[0] + "-", "");
                            var pkgDetails = repoClientPackage.GetPackageDetailsByPackageName(chekModel.ClientRowID.ToString(), pkgnm).Where(p => p.AntecedentSelected == 1);
                            chekModel.ClientCheckRowID = 0;
                            foreach (var item in pkgDetails)
                            {
                                //chekModel.ClientPackageRowID = item.ClientPackageRowID;
                                //repoPQCandidateCheck.AddCandidateCheck(chekModel);
                                //repoPQCandidateCheck.SaveChanges();
                                cc.CandidateCheckMoveToPQCandidate(chekModel.ClientRowID, chekModel.PersonalRowID, item.ClientPackageRowID, chekModel.ClientCheckRowID);
                            }
                        }
                    }
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
        }

        int SavePackageOrCheckWithCandidateNew(AddPQPersonalViewModel model)
        {
            int CheckOrPackage = 0;
            try
            {
                ClientCustomize cc = new ClientCustomize();
                AddPQCandidateCheckViewModel chekModel = new AddPQCandidateCheckViewModel();
                chekModel.ClientRowID = model.ClientRowID;
                chekModel.PersonalRowID = model.PersonalRowID;
                string[] strChkPkg = model.CandidateCheckOrPackage.Split(',');
                foreach (var ChkPkg in strChkPkg)
                {
                    string[] strIds = ChkPkg.Split('-');
                    if (!string.IsNullOrEmpty(strIds[0]))
                    {
                        if (strIds[0] == "Check")
                        {
                            int ClientCheckRowID = Convert.ToInt32(strIds[1]);
                            var ChekData = repoClientCheck.GetChecksByClientId(model.ClientRowID).Where(p => p.ClientCheckRowID == ClientCheckRowID && p.AntecedentSelected == 1);
                            chekModel.ClientPackageRowID = 0;
                            foreach (var item in ChekData)
                            {
                                CheckOrPackage = 1;
                                cc.CandidateCheckMoveToPQCandidate(chekModel.ClientRowID, chekModel.PersonalRowID, chekModel.ClientPackageRowID, item.ClientCheckRowID); //item.SubCheckRowID is subCheckFamilyID
                                if (item.CheckFamilyRowID == 5 && chekModel.ClientRowID == 249)
                                {
                                    new API().UpdateAPINewCaseInitiateStatus(chekModel.PersonalRowID, chekModel.ClientRowID.ToString(), "AddCaseCRC");
                                }
                                else
                                {
                                    new API().UpdateAPINewCaseInitiateStatus(chekModel.PersonalRowID, chekModel.ClientRowID.ToString(), "AddCase");
                                }
                            }
                        }
                        if (strIds[0] == "Package")
                        {
                            string pkgnm = ChkPkg.Replace(strIds[0] + "-", "");
                            var pkgDetails = repoClientPackage.GetPackageDetailsByPackageName(chekModel.ClientRowID.ToString(), pkgnm).Where(p => p.AntecedentSelected == 1);
                            chekModel.ClientCheckRowID = 0;
                            foreach (var item in pkgDetails)
                            {
                                CheckOrPackage = 1;
                                cc.CandidateCheckMoveToPQCandidate(chekModel.ClientRowID, chekModel.PersonalRowID, item.ClientPackageRowID, chekModel.ClientCheckRowID);
                            }
                        }
                    }
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return CheckOrPackage;
        }

        void EntryTbldataEntry(AddPQPersonalBulkImportViewModel model)
        {
            try
            {
                ClientCustomize cc = new ClientCustomize();
                AddPQCandidateCheckViewModel chekModel = new AddPQCandidateCheckViewModel();
                chekModel.ClientRowID = model.ClientRowID;
                chekModel.PersonalRowID = model.PersonalRowID;
                string[] strChkPkg = model.CandidateCheckOrPackage.Split(',');
                foreach (var ChkPkg in strChkPkg)
                {
                    string[] strIds = ChkPkg.Split('-');
                    if (!string.IsNullOrEmpty(strIds[0]))
                    {
                        if (strIds[0] == "Check")
                        {
                            int ClientCheckRowID = Convert.ToInt32(strIds[1]);
                            var ChekData = repoClientCheck.GetChecksByClientId(model.ClientRowID).Where(p => p.ClientCheckRowID == ClientCheckRowID);
                            chekModel.ClientPackageRowID = 0;
                            foreach (var item in ChekData)
                            {
                                if (item.SubCheckRowID.ToString() == "2" || item.SubCheckRowID.ToString() == "13" || item.SubCheckRowID.ToString() == "4" || item.SubCheckRowID.ToString() == "226" ||
                                    item.SubCheckRowID.ToString() == "29" || item.SubCheckRowID.ToString() == "546" || item.SubCheckRowID.ToString() == "206" || item.SubCheckRowID.ToString() == "232"
                                    || item.SubCheckRowID.ToString() == "136" || item.SubCheckRowID.ToString() == "213" || item.SubCheckRowID.ToString() == "222" || item.SubCheckRowID.ToString() == "214"
                                     || item.SubCheckRowID.ToString() == "259" || item.SubCheckRowID.ToString() == "215" || item.SubCheckRowID.ToString() == "218" || item.SubCheckRowID.ToString() == "260"
                                     || item.SubCheckRowID.ToString() == "216" || item.SubCheckRowID.ToString() == "23" || item.SubCheckRowID.ToString() == "24" || item.SubCheckRowID.ToString() == "25" || item.SubCheckRowID.ToString() == "430" || item.SubCheckRowID.ToString() == "416")
                                {
                                    cc.AddCase_Initiation_CRC_ID_WithDataEntry(item.SubCheckRowID.ToString(), item.ClientRowID, item.CheckFamilyRowID.ToString());
                                }

                            }
                        }
                        if (strIds[0] == "Package")
                        {
                            string pkgnm = ChkPkg.Substring(8);


                            var pkgDetails = repoClientPackage.GetPackageDetailsByPackageName(chekModel.ClientRowID.ToString(), pkgnm);
                            var checkDetails = pkgDetails.Where(x => new[] { 2, 13, 4, 226, 29, 546, 206, 232, 136, 213, 222, 214, 259, 215, 218, 260, 216, 23, 24, 25, 430, 416 }.Contains(x.SubCheckRowID)).ToList();
                            chekModel.ClientCheckRowID = 0;
                            foreach (var item in checkDetails)
                            {
                                cc.AddCase_Initiation_CRC_ID_WithDataEntry(item.SubCheckRowID.ToString(), item.ClientRowID, item.CheckFamilyRowID.ToString());
                            }
                        }

                    }
                }
            }
            catch (Exception)
            {

                throw;
            }
        }



