                {

                    FldPathDoc = ConfigurationManager.AppSettings[FolderNameForSave.Trim().ToLower()].ToString();

                    string existFile = repoPQVerifiedUploadDoc.ExistFileByPersonalIdSubCheckIdDocTypeNew(PersonalRowID, SubCheckRowID, DocumentType, FileName + ext);
                    if (!string.IsNullOrEmpty(existFile))
                    {
                        string path = Server.MapPath(FldPathDoc + existFile);
                        FileInfo file = new FileInfo(path);
                        if (file.Exists)//check file exsit or not
                        {
                            file.Delete();
                        }
                    }


                    proImg = FileName + ext;
                    if (ext.ToLower() == ".webp")
                    {
                        proImg = FileName + ".jpg";
                        string jpgPath = Server.MapPath(FldPathDoc + proImg);
                        using (var image = new MagickImage(UploadDoc.InputStream))
                        {
                            image.Format = MagickFormat.Jpeg;
                            image.Quality = 90;
                            image.Write(jpgPath);
                        }
                    }
                    else
                    {
                        UploadDoc.SaveAs(Server.MapPath(FldPathDoc + proImg));
                    }
                    DocModel.FileName = Path.GetFileName(proImg);
                    DocModel.FilePath = FldPathDoc;
                    DocModel.UploadDate = DateTime.Now;
                    DocModel.StatusDocxConvert = 0;
                    DocModel.StatusPDF2DOCXConvert = 0;
                    DocModel.PDF_FileName = "";
                    DocModel.Status = 1;
                    DocModel.Remarks = remarks;
                    int results = repoPQVerifiedUploadDoc.AddPQVerifiedUploadDocNew(DocModel);

                    if (SubCheckRowID == 799 && (Int32.Parse(Session["Clientrowid"].ToString()) == 317 || Int32.Parse(Session["Clientrowid"].ToString()) == 327) && (DocumentType == "AadhaarCard" || DocumentType == "PANCard") && ext == ".pdf")
                    {
                        PdfImage(PersonalRowID);
                    }
                }
                else
                {
                    DocModel.FileName = "NA";
                    DocModel.FilePath = "NA";
                }


            }
            catch (Exception ex)
            {
                string str = ex.Message;
                throw;
            }
        }
        private void SplitSingleLargePagePdf(string pdfFilePath, string outputPath, string pdfFileName, float absoluteY)
        {
            PdfReader reader = new PdfReader(pdfFilePath);
            Document document = null;
            //document = new Document(PageSize.A4);
            document = new Document();
            PdfWriter writer = PdfWriter.GetInstance(document, new FileStream(outputPath + "\\" + pdfFileName, FileMode.Create));
            writer.CloseStream = false;
            document.Open();
            //copy the page from the source pdf           
            PdfContentByte directcontent = writer.DirectContent;
            PdfImportedPage page = writer.GetImportedPage(reader, 1);
            iTextSharp.text.Image image = iTextSharp.text.Image.GetInstance(page);
            //image.SetAbsolutePosition(-9, 25);
            image.SetAbsolutePosition(0, absoluteY);
            //center the certificate
            directcontent.AddImage(image);
            document.NewPage();
            document.Close();
            reader.Close();
        }
        public void SavePQVerifiedUploadCaseDoc(int PersonalRowID = 0, string DocumentUploadFrom = "", string DocumentType = "", string FolderNameForSave = "", HttpPostedFileBase UploadDoc = null, string remarks = "", bool NADoc = false, bool SaveFromAPI = false)
        {
            try
            {
                string secRefId = string.Empty;
                if (SaveFromAPI)
                {
                    DataTable dtPerInfo = cc.GetPersonalInfo(PersonalRowID);
                    if (dtPerInfo.Rows.Count > 0)
                    {
                        secRefId = dtPerInfo.Rows[0]["CompanyRefNo"].ToString();
                    }
                }
                else
                {
                    secRefId = Session["SecuritasRefID"].ToString();
                }

                AddPQVerifiedUploadCaseDocViewModel DocModel = new AddPQVerifiedUploadCaseDocViewModel();
                DocModel.PersonalRowID = PersonalRowID;
                DocModel.DocumentUploadFrom = DocumentUploadFrom; //  Provided / Verified
                DocModel.DocumentType = DocumentType; //Name of the selected docs
                if (!NADoc)
                {
                    string FileName = (secRefId + " " + DocumentType + "_" + DateTime.Now.ToString()).Replace(" ", "_").Replace("-", "_").Replace(":", "_").Replace("/", "_");
                    if (FileName.Contains("24/7CPL_"))
                    {
                        FileName = FileName.Replace("/", "-");
                    }
                    string FldPathDoc = string.Empty;
                    FldPathDoc = ConfigurationManager.AppSettings[FolderNameForSave.Trim().ToLower()].ToString();

                    //string existFile = repoPQVerifiedUploadCaseDoc.ExistFileByPersonalIdAndDocType(PersonalRowID, DocumentType);
                    string existFile = repoPQVerifiedUploadCaseDoc.ExistcaseFileByPersonalIdAndDocType(PersonalRowID, DocumentType, FileName);
                    if (!string.IsNullOrEmpty(existFile))
                    {
                        string path = Server.MapPath(FldPathDoc + existFile);
                        FileInfo file = new FileInfo(path);
                        if (file.Exists)//check file exsit or not
                        {
                            file.Delete();
                        }
                    }

                    string proImg = string.Empty;
                    string ext = Path.GetExtension(UploadDoc.FileName).ToLower();
                    proImg = FileName + ext;
                    if (ext.ToLower() == ".webp")
                    {
                        proImg = FileName + ".jpg";
                        string jpgPath = Server.MapPath(FldPathDoc + proImg);
                        using (var image = new MagickImage(UploadDoc.InputStream))
                        {
                            image.Format = MagickFormat.Jpeg;
                            image.Quality = 90;
                            image.Write(jpgPath);
                        }
                    }
                    else
                    {
                        UploadDoc.SaveAs(Server.MapPath(FldPathDoc + proImg));
                    }
                    DocModel.FileName = Path.GetFileName(proImg);
                    DocModel.FilePath = FldPathDoc;
                }
                else
                {
                    DocModel.FileName = "NA";
                    DocModel.FilePath = "NA";
                }
                DocModel.UploadDate = DateTime.Now;
                DocModel.Status = 1;
                DocModel.Remarks = remarks;
                repoPQVerifiedUploadCaseDoc.AddPQVerifiedUploadCaseDoc(DocModel);
                repoPQVerifiedUploadCaseDoc.SaveChanges();
                //////----------For Accenture-----LOA//Bgv Page---------
                ////ClientCustomize c = new ClientCustomize();
                ////if (DocModel.DocumentType == "Letter Of Authorization" || DocModel.DocumentType == "BGV Page")
                ////{
                ////    c.PQVerifiedUploadDocs_Insert(DocModel.PersonalRowID, DocModel.DocumentUploadFrom, DocModel.DocumentType, DocModel.FileName, DocModel.FilePath, DocModel.Remarks);
                ////}
                //////------------------------------------------------------------
            }
            catch (Exception ex)
            {
                string str = ex.Message;
                throw;
            }
        }
        [NonAction]
        private int IfAllCheckDocUploadedByDEScanCaseMove(int PersonalRowID = 0)
        {
            try
            {

                int res = 0;
                if (PersonalRowID > 0)
                {
                    var CandidateChecks = repoPQCandidateCheck.GetCandidateChecks(PersonalRowID);
                    if (CandidateChecks != null && CandidateChecks.Count() > 0)
                    {
                        bool Result = true;
                        foreach (var item in CandidateChecks)
                        {
                            if (item.ClientPackageRowID > 0)
                            {
                                var chkData = repoClientPackage.GetPackageDetailsById(item.ClientPackageRowID);
                                Result = repoPQVerifiedUploadDoc.IsExistsTempChecksInUploadDocList(item.PersonalRowID, chkData.SubCheckRowID);
                            }
                            else
                            {
                                var chkData = repoClientPackage.GetPackageDetailsById(item.ClientCheckRowID);
                                Result = repoPQVerifiedUploadDoc.IsExistsTempChecksInUploadDocList(item.PersonalRowID, chkData.SubCheckRowID);
                            }
                            if (Result)
                            {
                                break;
                            }
                        }
                        if (Result == false)
                        {
                            repoPQPersonal.UpdatePQPersonalForQC(PersonalRowID, "DEO");
                            res = repoPQPersonal.SaveChanges();
                            if (res > 0)
                            {
                                #region Case/Check Action History Save 
                                clsCommonMethods.AddCaseActionHistory(PersonalRowID, "DEC", "Data Entry Completed");
                                #endregion
                            }
                        }
                    }
                }
                return res;
            }
            catch (Exception)
            {
                throw;
            }
        }

