        [SessionExpireFilterAttribute]
        [HttpGet]
        public void downloadResearchDoc(string FileName)
        {
            string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["provideddocuments"].ToString();
            string aa = FldPathDoc + FileName;
            if (System.IO.File.Exists(Server.MapPath(FldPathDoc) + FileName))
            {
                System.Web.HttpResponse response = System.Web.HttpContext.Current.Response;
                response.ClearContent();
                response.Clear();
                response.ContentType = "text/plain";
                response.AddHeader("Content-Disposition",
                                   "attachment; filename=" + aa + ";");
                response.TransmitFile(Server.MapPath(aa));
                response.Flush();
                response.End();
            }


        }

