        [HttpGet]
        [SessionExpireFilterAttributeClient]
        public void ExportCandidateDuplicateSearch(string TicketNo)
        {
            try
            {
                int ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                short ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                DataTable ds = new DataTable();
                ClientCustomize cc = new ClientCustomize();
                ds = cc.GetDuplicateReferenceDetails(ClientRowID, TicketNo);
                DataTable TempTable = new DataTable();
                TempTable = ds;
                string[] selectedColumns = new[] { "TicketId", "Name", "MiddleName", "LastName", "DOB", "MobileNo", "EmailId", "DuplicateStatus" };

                DataView view = new System.Data.DataView(TempTable);
                DataTable dt = view.ToTable("Details", false, selectedColumns);

                using (ClosedXML.Excel.XLWorkbook wb = new ClosedXML.Excel.XLWorkbook())
                {
                    var ws = wb.Worksheets.Add(dt);
                    ws.Tables.FirstOrDefault().ShowAutoFilter = false;
                    //wb.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    wb.Style.Font.Bold = true;
                    Response.Clear();
                    Response.Buffer = true;
                    Response.Charset = "";
                    Response.ContentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
                    Response.AddHeader("content-disposition", "attachment;filename=PendingWithCandidate.xlsx");

                    using (MemoryStream MyMemoryStream = new MemoryStream())
                    {
                        wb.SaveAs(MyMemoryStream);
                        MyMemoryStream.WriteTo(Response.OutputStream);
                        Response.Flush();
                        Response.End();
                    }
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
        }


