        #region ********** Code For AutoSave Case/Check Document  **********

        public async Task<ActionResult> DownloadAllDocsAsZip(string UniqueReferenceID, string Types, int PersonalRowID = 0)
        {
            ClientCustomize cc = new ClientCustomize();
            DataTable dt = new DataTable();

            if (string.IsNullOrEmpty(UniqueReferenceID))
                return Content("Invalid Reference ID.");

            if (Types.ToUpper().Trim() == "DOCUMENTDETAILS")
            {
                dt = cc.GetAPICheckDetail(UniqueReferenceID, Types);
                if (dt.Rows.Count == 0)
                {
                    dt = cc.GetAPICheckDetail_Data(UniqueReferenceID, Types);
                }
            }

            string[] docList = null;
            if (dt.Rows.Count > 0)
            {
                int ClientID = Convert.ToInt32(dt.Rows[0]["ClientID"]);
                if (ClientID == 113 && Types.ToUpper().Trim() == "DOCUMENTDETAILS")
                {
                    WebClient myWebClient = new WebClient();
                    string downloadedString = myWebClient.DownloadString(
                        "https://api.walsonsverify.com/CaseDocsFromAPIList?ReferenceId=" + UniqueReferenceID);
                    string str = downloadedString.Replace("[", "").Replace("]", "").Replace("\"", "");
                    docList = str.Split(',');
                }
            }
            else
            {
                //Get the same document list again using your existing API call
                WebClient myWebClient = new WebClient();
                string downloadedString = myWebClient.DownloadString(
                    "https://api.weverifyglobal.com/CaseDocsFromAPIList?ReferenceId=" + UniqueReferenceID);
                string str = downloadedString.Replace("[", "").Replace("]", "").Replace("\"", "");
                docList = str.Split(',');
            }

            if (docList == null || docList.Length == 0)
                return Content("No files found for this candidate.");

            //Create a ZIP archive in memory
            using (var memoryStream = new MemoryStream())
            {
                using (var zip = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                {
                    using (var httpClient = new HttpClient())
                    {
                        foreach (var fileName in docList.Where(f => !string.IsNullOrWhiteSpace(f)))
                        {
                            try
                            {
                                string url;
                                string[] tokens = fileName.Split(new[] { "_", "-" }, StringSplitOptions.None);
                                string clientId = tokens.Length > 1 ? tokens[1] : "";

                                if (clientId == "113")
                                    url = "https://api.walsonsverify.com/CaseDocsFromAPIMic?fileName=" + fileName;
                                else
                                    url = "https://api.weverifyglobal.com/CaseDocsFromAPI?fileName=" + fileName;

                                // Download the document bytes
                                var data = await httpClient.GetByteArrayAsync(url);

                                // Add each file to the ZIP
                                var entry = zip.CreateEntry(fileName, CompressionLevel.Fastest);
                                using (var entryStream = entry.Open())
                                {
                                    await entryStream.WriteAsync(data, 0, data.Length);
                                }
                            }
                            catch
                            {
                                // Skip any file that fails
                            }
                        }
                    }
                }

                memoryStream.Position = 0;
                string zipFileName = $"{UniqueReferenceID}_{DateTime.Now:ddMMyyyy}_AllDocuments.zip";
                string fullZipPath = Path.Combine(Path.GetTempPath(), zipFileName);

                System.IO.File.WriteAllBytes(fullZipPath, memoryStream.ToArray());

                //Create CustomHttpPostedFileBase
                var wrappedFile = new WebAppBGV.Services.CustomHttpPostedFileBase(fullZipPath);

                if (PersonalRowID > 0)
                {
                    //Call Save Function
                    SavePQVerifiedUploadCaseDoc(PersonalRowID, "Provided", "Other Doc For Case", "provideddocuments", wrappedFile, "File_AutoUpload_From_API", false, true);

                    //Call Common Method
                    fnCallCommonMethodAfterUploadCaseDoc(PersonalRowID, "");
                }

                //Delete Temp File
                System.IO.File.Delete(fullZipPath);

                //Return File to User
                return File(memoryStream.ToArray(), "application/zip", zipFileName);
            }
        }

        [HttpPost]
        public ActionResult fnUploadAPIDocumentBGVPage(int PersonalRowID, string DocumentType)
        {
            try
            {
                var file = Request.Files["uploadDoc"];
                if (file != null && file.ContentLength > 0 && PersonalRowID > 0)
                {
                    //Call Save Function                    
                    SavePQVerifiedUploadCaseDoc(PersonalRowID, "Provided", DocumentType, "provideddocuments", file, "File_AutoUpload_From_API", false, true);

                    //Call Common Method
                    fnCallCommonMethodAfterUploadCaseDoc(PersonalRowID, "");

                    return Json(new { success = true, message = "File received and saved successfully." });
                }
                else
                {
                    return Json(new { success = false, message = "No file received/Upload failed." });
                }
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }

