                            ViewBag.url7 = url;
                        }
                        else if (i == 8)
                        {
                            ViewBag.data8 = lists;
                            ViewBag.url8 = url;
                        }
                        else if (i == 9)
                        {
                            ViewBag.data9 = lists;
                            ViewBag.url9 = url;
