        public ActionResult GetClientDoc(string ImageName, string CompanyRefNo, string Casestatus = "")
        {
            string imgname = clsCommonMethods.PDecrypt(ImageName);
            CompanyRefNo = clsCommonMethods.PDecrypt(CompanyRefNo);
            string extension = Path.GetExtension(imgname);
            //string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["CandidateReportdoc"].ToString();
            string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["ClientUploadedDocuments_New"].ToString();
            byte[] fileBytes = null;
            if (System.IO.File.Exists(Server.MapPath(FldPathDoc) + imgname))
            {
                fileBytes = System.IO.File.ReadAllBytes(Server.MapPath(FldPathDoc) + imgname);
            }
            if (fileBytes != null)
                return File(fileBytes, MediaTypeNames.Application.Octet, CompanyRefNo + extension);

            {
                return RedirectToAction("AllocatedDEScannerJob", new { CaseStatus = Casestatus });
            }
        }


