        public string Update_NA_NP(string Value = "")
        {
            string finalvalue = "";
            if (Convert.ToString(Value) != "")
            {
                if (Value.ToLower() == "na")
                {
                    finalvalue = "Not Applicable";
                }
                else if (Value.ToLower() == "np")
                {
                    finalvalue = "Not Provided";
                }
                else
                {
                    finalvalue = Value;
                }
            }
            return finalvalue;
        }


