                int ClientRowID = FC["ClientRowID"] != "" ? Convert.ToInt32(FC["ClientRowID"]) : 0;
                string CaseStatus = Convert.ToString(FC["CaseStatus"]);
                string version = Convert.ToString(FC["version"]);
                string PersonalIds = Convert.ToString(FC["PersonalIds"]);
                string RecievingfromDate = Convert.ToString(FC["RecievingfromDate"]);
                string RecievingToDate = Convert.ToString(FC["RecievingToDate"]);
                if (!string.IsNullOrEmpty(PersonalIds))
                {
                    UpdatePQPersonalViewModel personalmodel = new UpdatePQPersonalViewModel();
                    DateTime currDateTime = DateTime.Now;
                    personalmodel.AllocatedBy = Convert.ToInt16(Session["TeamMemberRowID"]);
                    //int[] personalId = PersonalIds.Split(',').Select(str => int.Parse(str)).ToArray();
                    int[] personalId = PersonalIds.Split(',').Select(str => int.Parse(str.Trim())).Distinct().ToArray();
                    ClientCustomize cc = new ClientCustomize();
                    DataBaseConnections con = new DataBaseConnections();
                    foreach (var item in personalId)
                    {
                        personalmodel.PersonalRowID = item;
                        int PersonalRowid = personalmodel.PersonalRowID;
                        var DTCheckList = cc.GetPQCandidateCheckList(personalmodel.PersonalRowID, "DataEntry");
                        if (DTCheckList.Rows.Count > 0)
                        {
                            for (int i = 0; i < DTCheckList.Rows.Count; i++)
                            {
                                int SubCheckid = Convert.ToInt32(DTCheckList.Rows[i]["SubCheckFamilyID"]);
                                int ClientRowid = Convert.ToInt32(DTCheckList.Rows[i]["ClientRowID"]);
                                int CheckStatusID = Convert.ToInt32(DTCheckList.Rows[i]["CheckStatusID"]);
                                int CheckFamilyRowID = Convert.ToInt32(DTCheckList.Rows[i]["CheckFamilyRowID"]);
                                int CandidateCheckRowId = Convert.ToInt32(DTCheckList.Rows[i]["CandCheckRowID"]);
                                string CompanyRefNo = Convert.ToString(DTCheckList.Rows[i]["CompanyRefNo"]);
                                if (CheckStatusID == 14) //for Complete
                                {
                                    if (CheckFamilyRowID == 2)
                                    {
                                        var Methods = cc.GetAddressMode(ClientRowid);
                                        var candCheckRowid = CandidateCheckRowId;
                                        DataTable DtCheck = new DataTable();
                                        DtCheck = cc.GetCheckDetails(candCheckRowid);
                                        string CheckUniqueID = (DtCheck.Rows[0]["CheckUniqueID"].ToString());
                                        if (Methods.Any(mode => mode.ToLower().Contains("digital")))
                                        {
                                            cc.AutoPartnerAllocation(candCheckRowid, 140, "digital");
                                            cc.UpdateDataEntryToDataEntryQCValue(personalmodel.PersonalRowID, Convert.ToInt16(SubCheckid));
                                            cc.UpdateCheckStatus(personalmodel.PersonalRowID, Convert.ToInt16(SubCheckid), 1, 27, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                                            #region Save LogTransaction Details
                                            clsCommonMethods.AddPQLogTrasaction(personalmodel.PersonalRowID, "ManagerAllocationToTeamLeader", "Allocated-PTR", CheckUniqueID, "Update");
                                            #endregion

                                            #region Case/Check Action History Save 
                                            clsCommonMethods.AddCheckActionHistory(personalmodel.PersonalRowID, Convert.ToInt16(SubCheckid), "Allocated-PTR", "Team Member Allocated To Partner");
                                            #endregion


                                        }
                                        else if (Methods.Any(mode => mode.ToLower().Contains("physical")) || Methods.Any(mode => mode.ToLower().Contains("kyc utility")))
                                        {
                                            cc.AutoPartnerAllocation(candCheckRowid, 141, "physical");
                                            cc.UpdateDataEntryToDataEntryQCValue(personalmodel.PersonalRowID, Convert.ToInt16(SubCheckid));
                                            cc.UpdateCheckStatus(personalmodel.PersonalRowID, Convert.ToInt16(SubCheckid), 1, 27, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                                            #region Save LogTransaction Details
                                            clsCommonMethods.AddPQLogTrasaction(personalmodel.PersonalRowID, "ManagerAllocationToTeamLeader", "Allocated-PTR", CheckUniqueID, "Update");
                                            #endregion

                                            #region Case/Check Action History Save 
                                            clsCommonMethods.AddCheckActionHistory(personalmodel.PersonalRowID, Convert.ToInt16(SubCheckid), "Allocated-PTR", "Team Member Allocated To Partner");
                                            #endregion
                                        }
                                        else if (Methods.Any(mode => mode.ToLower().Contains("verbal")))
                                        {
                                            cc.AutoPartnerAllocation(candCheckRowid, 1, "verbal");
                                            cc.UpdateDataEntryToDataEntryQCValue(personalmodel.PersonalRowID, Convert.ToInt16(SubCheckid));
                                            cc.UpdateCheckStatus(personalmodel.PersonalRowID, Convert.ToInt16(SubCheckid), 1, 27, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                                            #region Save LogTransaction Details
                                            clsCommonMethods.AddPQLogTrasaction(personalmodel.PersonalRowID, "ManagerAllocationToTeamLeader", "Allocated-PTR", CheckUniqueID, "Update");
                                            #endregion

                                            #region Case/Check Action History Save 
                                            clsCommonMethods.AddCheckActionHistory(personalmodel.PersonalRowID, Convert.ToInt16(SubCheckid), "Allocated-PTR", "Team Member Allocated To Partner");
                                            #endregion
                                        }
                                        else
                                        {
                                            cc.UpdateDataEntryToDataEntryQCValue(personalmodel.PersonalRowID, Convert.ToInt16(SubCheckid));
                                            cc.UpdateCheckStatus(item, Convert.ToInt16(SubCheckid), 1, 16, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                                            clsCommonMethods.AddCheckActionHistory(item, Convert.ToInt16(SubCheckid), "DataEntry-QC", "Bulk Case Movements");

                                        }
                                    }
                                    else if (CheckFamilyRowID == 26)
                                    {
                                        int[] ClientRowIds = { 860, 1160, 1199 };
                                        bool isClientRowId = false;
                                        if (Array.Find(ClientRowIds, element => element == ClientRowid) > 0)
                                        {
                                            isClientRowId = true;
                                        }
                                        try
                                        {
                                            var idtblDT = cc.getNationalCheckFromDataEntry(PersonalRowid, SubCheckid);
                                            string IDNumber = Convert.ToString(idtblDT.Rows[0]["IDNumber"]);
                                            string Candidate_Name = Convert.ToString(idtblDT.Rows[0]["CandidateName"]);
                                            string IdentityType = Convert.ToString(idtblDT.Rows[0]["IdentityType"]);
                                            string Identity_Type = Convert.ToString(idtblDT.Rows[0]["IdentityType"]);
                                            string CandidateName = Convert.ToString(idtblDT.Rows[0]["CandidateName"]);
                                            string CheckUniqueID = Convert.ToString(idtblDT.Rows[0]["CheckUniqueID"]);
                                            int clientRowid = ClientRowid;
