        [HttpPost]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult BulkMovementDETMToDEQC(FormCollection FC, string action)
        {
            DashboardDEListViewModel model = new DashboardDEListViewModel();
            try
            {
                string sort = "";
                string sortDir = "asc";
                string Search = Convert.ToString(FC["Search"]);
                int ClientRowID = FC["ClientRowID"] != "" ? Convert.ToInt32(FC["ClientRowID"]) : 0;
                string CaseStatus = Convert.ToString(FC["CaseStatus"]);
                string version = Convert.ToString(FC["version"]);
                string PersonalIds = Convert.ToString(FC["PersonalIds"]);
                string RecievingfromDate = Convert.ToString(FC["RecievingfromDate"]);
                string RecievingToDate = Convert.ToString(FC["RecievingToDate"]);
                if (!string.IsNullOrEmpty(PersonalIds))
                {
                    UpdatePQPersonalViewModel personalmodel = new UpdatePQPersonalViewModel();
                    DateTime currDateTime = DateTime.Now;
                    personalmodel.AllocatedBy = Convert.ToInt16(Session["TeamMemberRowID"]);
                    int[] personalId = PersonalIds.Split(',').Select(str => int.Parse(str)).ToArray();
                    ClientCustomize cc = new ClientCustomize();

                    foreach (var item in personalId)
                    {
                        personalmodel.PersonalRowID = item;

                        var DTCheckList = cc.GetPQCandidateCheckList(personalmodel.PersonalRowID);
                        if (DTCheckList.Rows.Count > 0)
                        {
                            for (int i = 0; i < DTCheckList.Rows.Count; i++)
                            {
                                int SubCheckid = Convert.ToInt32(DTCheckList.Rows[i]["SubCheckFamilyID"]);
                                int ClientRowid = Convert.ToInt32(DTCheckList.Rows[i]["ClientRowID"]);
                                int CheckStatusID = Convert.ToInt32(DTCheckList.Rows[i]["CheckStatusID"]);
                                int CheckFamilyRowID = Convert.ToInt32(DTCheckList.Rows[i]["CheckFamilyRowID"]);
                                int CandidateCheckRowId = Convert.ToInt32(DTCheckList.Rows[i]["CandCheckRowID"]);
                                if (CheckStatusID == 8) //for Complete
                                {

                                    int checkstStatusID = 14;
                                    cc.CheckMovementProcessCompletionDate(Convert.ToInt32(item), SubCheckid, "DataEntry-TM");
                                    if (checkstStatusID > 0)
                                    {
                                        cc.UpdateCheckStatus(Convert.ToInt32(item), SubCheckid, 1, checkstStatusID, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                                    }
                                    #region Case/Check Action History Save 

                                    clsCommonMethods.AddCheckActionHistory(item, Convert.ToInt16(SubCheckid), "Completed", "");
                                    #endregion


                                }
                            }
                        }
                    }
                    ViewBag.ErrorMsg = "Records Update Successfully !.";


                }
                int pageSize = clsGlobalCommon.PageSize;
                short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                string designation = Session["Designation"].ToString();
                model = repoIDashboardDataEntry.GetDETeamLeaderDashBoardInfo1(1, pageSize, sort.ToLower(), sortDir.ToLower(), Search, CaseStatus, designation, teamMemerRowId, Convert.ToInt16(ClientRowID));
                BindClientListBaseOnLogin(teamMemerRowId);
                PQPersonalSearchPagedModel SearchModel = new PQPersonalSearchPagedModel();
                SearchModel.ClientRowId = ClientRowID > 0 ? ClientRowID.ToString() : "";
                SearchModel.Search = Search;
                SearchModel.RecievingFromDate = RecievingfromDate;
                SearchModel.CompletedFromDate = "";
                SearchModel.RecievingToDate = RecievingToDate;
                SearchModel.CompletedToDate = "";
                model.ItemSearch = SearchModel;

                if (model == null)
                {
                    ViewBag.ErrorMsg = "No item found!";
                }
                ViewBag.CaseStatus = CaseStatus.ToString();
                ViewBag.version = version.ToString();
                Session["CaseStatus"] = CaseStatus.ToString();
                Session["version"] = version.ToString();
                if (action == "Export Excel")
                {
                    ExcelExportDENew(ClientRowID.ToString(), CaseStatus, Search);
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(model);
        }


