            try
            {
                string CompanyRefNo = fm["CompanyRefNo"].ToString();
                string Clientname = fm["Clientname"].ToString();
                string[] Strvalues = CompanyRefNo.Split('-');
                string StrFirstValues = Convert.ToString(Strvalues[0]);
                string StrLastValues = Convert.ToString(Strvalues[1]) + "-" + Convert.ToString(Strvalues[2]) + "-" + Convert.ToString(Strvalues[3]) + "-" + Convert.ToString(Strvalues[4]);
                string StrUpdateValues = StrFirstValues + "-" + Clientname + "-" + StrLastValues;
                cc.UpdateCompanyRefNo(259, CompanyRefNo, StrUpdateValues);
                ViewBag.CompanyRefNo = StrUpdateValues;
                ViewBag.msg = "Updated Successfully.";
            }
            catch (Exception ex)
            {
                ViewBag.msg = Convert.ToString(ex.Message);
            }
            return View();
        }

