        public bool tcsUANCheckViaBGVForm(int PersonalRowId, int SubCheckRowId, string FldPathDoc)
        {
            bool Status = true;
            DataBaseConnections DC = new DataBaseConnections();
            try
            {
                var UANDt = DC.GetllmtechUANDetails(0, PersonalRowId, "", "", "", "", 0, SubCheckRowId);
                if (UANDt.Rows.Count > 0)
                {
                    bool UANStatus = true;
                    string JsonString = Convert.ToString(UANDt.Rows[0]["JsonString"]);
                    var model = JsonConvert.DeserializeObject<llmtechUANRoot>(JsonString);
                    var bgvformDT = DC.GetCandidateBGCForm(PersonalRowId);
                    if (bgvformDT.Rows.Count > 0)
                    {
                        var uanDetails = model.data.result;
                        string bgvform = Convert.ToString(bgvformDT.Rows[0]["FileName"]);
                        string CandidateName = Convert.ToString(bgvformDT.Rows[0]["CandidateFullName"]);
                        string FatherName = Convert.ToString(bgvformDT.Rows[0]["FatherName"]);

                        string bgvFile = FldPathDoc + bgvform;
                        PDFOCR pDFOCR = new PDFOCR();
                        DataTable dt = new DataTable();
                        var bgvFormEmpDetails = pDFOCR.getOCRDatafromBDVForm(FldPathDoc, bgvFile);
                        if (bgvFormEmpDetails != null)
                        {
                            if (CandidateName.Trim().ToUpper() == uanDetails[0].name.Trim().ToUpper())
                            {
                                DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, "Candidate Name" + CandidateName.Trim().ToUpper() + " " + uanDetails[0].name.Trim().ToUpper(), "Success");
                            }
                            else
                            {
                                Status = false;
                                DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, "Candidate Name" + CandidateName.Trim().ToUpper() + " " + uanDetails[0].name.Trim().ToUpper(), "Failed");
                                return Status;
                            }
                            if (FatherName.Trim().ToUpper() == uanDetails[0].fatherOrHusbandName.Trim().ToUpper())
                            {
                                DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, "Father Name: " + FatherName.Trim().ToUpper() + "," + uanDetails[0].fatherOrHusbandName.Trim().ToUpper(), "Success");
                            }
                            else
                            {
                                Status = false;
                                DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, "Father Name: " + FatherName.Trim().ToUpper() + "," + uanDetails[0].fatherOrHusbandName.Trim().ToUpper(), "Failed");
                                return Status;
                            }
                            int uanEmp = uanDetails.Count;
                            int BGVFormEmp = bgvFormEmpDetails.EmpObj.Count;
                            if (BGVFormEmp < uanEmp)
                            {
                                Status = false;
                                DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, "BGV EMP:" + BGVFormEmp + " and UAN EMP:" + uanEmp, "Failed");
                                return Status;
                            }
                            else
                            {
                                DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, "BGV EMP:" + BGVFormEmp + " and UAN EMP:" + uanEmp, "Success");

                            }
                            foreach (var item in uanDetails)
                            {
                                string date_of_joining = "";
                                string date_of_exit = "";
                                if (Convert.ToString(item.dateOfJoining) != "")
                                {
                                    DateTime doj = Convert.ToDateTime(item.dateOfJoining);
                                    date_of_joining = doj.ToString("dd-MMM-yyyy");
                                }
                                if (Convert.ToString(item.dateOfExit) != "")
                                {
                                    DateTime doe = Convert.ToDateTime(item.dateOfExit);
                                    date_of_exit = doe.ToString("dd-MMM-yyyy");
                                }
                                var EmpObj = bgvFormEmpDetails.EmpObj;

                                bool EmployerName = false;
                                bool dateOfJoining = false;
                                bool dateOfExit = false;

                                foreach (var empI in EmpObj)
                                {
                                    if (item.establishmentName.ToUpper() == empI.NameofCompany.Trim().ToUpper())
                                    {
                                        string StartDate = "";
                                        string EndDate = "";
                                        if (Convert.ToString(empI.StartDate) != "")
                                        {
                                            DateTime doj = Convert.ToDateTime(empI.StartDate);
                                            StartDate = doj.ToString("dd-MMM-yyyy");
                                        }
                                        if (Convert.ToString(empI.EndDate) != "")
                                        {
                                            DateTime doe = Convert.ToDateTime(empI.EndDate);
                                            EndDate = doe.ToString("dd-MMM-yyyy");
                                        }
                                        EmployerName = true;
                                        if (date_of_joining == empI.StartDate.Trim())
                                        {
                                            dateOfJoining = true;
                                        }
                                        if (date_of_exit == empI.EndDate.Trim())
                                        {
                                            dateOfExit = true;
                                        }
                                    }

                                }
                                if (!EmployerName)
                                {
                                    Status = false;
                                    DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, item.establishmentName, "Failed");
                                    return Status;
                                }
                                else
                                {
                                    DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, item.establishmentName, "Success");
                                }
                                if (!dateOfExit)
                                {
                                    Status = false;
                                    DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, item.establishmentName + " " + date_of_exit, "Failed");
                                    return Status;
                                }
                                else
                                {
                                    DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, item.establishmentName + " " + date_of_exit, "Success");
                                }
                                if (!dateOfJoining)
                                {
                                    Status = false;
                                    DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, item.establishmentName + " " + date_of_joining, "Failed");
                                    return Status;
                                }
                                else
                                {
                                    DC.AddUANCheckToBGVFormCheckStatus(PersonalRowId, SubCheckRowId, item.establishmentName + " " + date_of_joining, "Success");
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception Ex)
            {
                return false;
            }

            return Status;
        }
        public string SavePQVerifiedUploadCaseDocUAN(int PersonalRowID = 0, string DocumentUploadFrom = "", string DocumentType = "", string FolderNameForSave = "", string UploadDoc = "", string remarks = "", bool NADoc = false, string secRefId = "")
        {
            try
            {
                var Timestamp = new DateTimeOffset(DateTime.UtcNow).ToUnixTimeSeconds().ToString();

                string FileName = "";
                string proImg = string.Empty;
                AddPQVerifiedUploadCaseDocViewModel DocModel = new AddPQVerifiedUploadCaseDocViewModel();
                DocModel.PersonalRowID = PersonalRowID;
                DocModel.DocumentUploadFrom = DocumentUploadFrom; //  Provided / Verified
                DocModel.DocumentType = DocumentType; //Name of the selected docs
                FileName = (secRefId + " " + DocumentType).Replace(" ", "_").Replace("-", "_") + "_" + Timestamp;
                if (!NADoc)
                {
                    if (FileName.Contains("24/7CPL_"))
                    {
                        FileName = FileName.Replace("/", "-");
                    }
                    string FldPathDoc = string.Empty;
                    FldPathDoc = ConfigurationManager.AppSettings[FolderNameForSave.Trim().ToLower()].ToString();

                    string existFile = repoPQVerifiedUploadCaseDoc.ExistcaseFileByPersonalIdAndDocType(PersonalRowID, DocumentType, FileName);
                    if (!string.IsNullOrEmpty(existFile))
                    {
                        string path = Server.MapPath(FldPathDoc + existFile);
                        FileInfo file = new FileInfo(path);
                        if (file.Exists)//check file exsit or not
                        {
                            file.Delete();
                        }
                    }


                    proImg = FileName + ".pdf";


                    string IronKey = System.Configuration.ConfigurationManager.AppSettings["IronKey"].ToString();
                    var Renderer = new IronPdf.ChromePdfRenderer();
                    IronPdf.License.LicenseKey = IronKey;
                    var pdf = Renderer.RenderHtmlAsPdf(UploadDoc);

                    pdf.SaveAs(Server.MapPath(FldPathDoc + proImg)); // Saves our PdfDocument object as a PDF

                    DocModel.FileName = Path.GetFileName(proImg);
                    DocModel.FilePath = FldPathDoc;
                }
                else
                {
                    DocModel.FileName = "NA";
                    DocModel.FilePath = "NA";
                }
                DocModel.UploadDate = DateTime.Now;
                DocModel.Status = 1;
                DocModel.Remarks = remarks;
                repoPQVerifiedUploadCaseDoc.AddPQVerifiedUploadCaseDoc(DocModel);
                repoPQVerifiedUploadCaseDoc.SaveChanges();

                return proImg;
            }
            catch (Exception ex)
            {
                string str = ex.Message;
                throw;
            }
        }
        private string GetIP_Address()
        {
            string myIPAddr = "";
            foreach (NetworkInterface ni in NetworkInterface.GetAllNetworkInterfaces())
            {
                if (ni.OperationalStatus == OperationalStatus.Up)
                {
                    foreach (UnicastIPAddressInformation ip in ni.GetIPProperties().UnicastAddresses)
                    {
                        if (ip.Address.AddressFamily == AddressFamily.InterNetwork)
                        {
                            myIPAddr += $" Interface: {ni.Name}, IP Address: {ip.Address} ";
                        }
                    }
                }
            }
            return myIPAddr.ToString();
        }

