            {
                DataTable dl = new DataTable();
                dt = cc.GetAPICheckDetail_DataByAntecedents(UniqueReferenceID, Types);
                if (dt.Rows.Count > 0)
                {
                    UniqueReferenceID = dt.Rows[0]["APIAutoID"].ToString();
                }
            }
            ViewBag.checkDetail = Types;
            ViewBag.PUniqueReferenceID = UniqueReferenceID;
            List<PatternDetailCheckModel> modelList = new List<PatternDetailCheckModel>();
            dt = cc.GetAPICheckDetail_Data(UniqueReferenceID, Types);
            if (dt.Rows.Count > 0)
            {
                string json = dt.Rows[0]["AntecedentValue"].ToString();
                ViewBag.checkDetail = dt.Rows[0]["Antecedent"].ToString();

                json = json.Replace("[", "").Replace("]", "");
                if (!string.IsNullOrEmpty(json))
                {
                    string[] parts1 = json.Split(new string[] { "}," }, StringSplitOptions.None);
                    if (Types == "gaplist")
                    {
                        List<GapListModel> modelList1 = new List<GapListModel>();
                        for (int i = 0; i <= parts1.Length - 1; i++)
                        {
                            if (i != parts1.Length - 1)
                            {
                                parts1[i] = parts1[i] + "}";
                            }

                            try
                            {
                                var obj = JsonConvert.DeserializeObject<GapListModel>(parts1[i]);
                                if (obj != null)
                                {
                                    modelList1.Add(obj);
                                }
                            }
                            catch (Exception ex)
                            {
                            }
                        }
                        ViewBag.data = modelList1;
                    }
                    else
                    {
                        for (int i = 0; i <= parts1.Length - 1; i++)
                        {
                            if (i != parts1.Length - 1)
                            {
                                parts1[i] = parts1[i] + "}";
                            }

                            try
                            {
                                var obj = JsonConvert.DeserializeObject<PatternDetailCheckModel>(parts1[i]);
                                if (obj != null)
                                {
                                    modelList.Add(obj);
                                }
                            }
                            catch (Exception ex)
                            {
                            }
                        }
                    }


                }

            }
            return PartialView(modelList);
        }

