        [HttpGet]
        public ActionResult CaseRemarksAPI(string UniqueReferenceID, string Types)
        {
            ClientCustomize cc = new ClientCustomize();
            DataTable dt = new DataTable();
            List<CaseRemarksAPIModel> modelList = new List<CaseRemarksAPIModel>();
            DataTable dl = new DataTable();

            dt = cc.GetAPICheckDetail_Data(UniqueReferenceID, Types);
            if (dt.Rows.Count > 0)
            {

                string json = dt.Rows[0]["AntecedentValue"].ToString();
                ViewBag.checkDetail = dt.Rows[0]["Antecedent"].ToString();

                json = json.Replace("[", "").Replace("]", "");
                if (!string.IsNullOrEmpty(json))
                {
                    string[] parts1 = json.Split(new string[] { "}," }, StringSplitOptions.None);

                    for (int i = 0; i <= parts1.Length - 1; i++)
                    {
                        if (i != parts1.Length - 1)
                        {
                            parts1[i] = parts1[i] + "}";
                        }

                        try
                        {
                            var obj = JsonConvert.DeserializeObject<CaseRemarksAPIModel>(parts1[i]);
                            if (obj != null)
                            {
                                modelList.Add(obj);
                            }
                        }
                        catch (Exception ex)
                        {
                        }
                    }
                }
            }
            return PartialView(modelList);
        }

        [HttpGet]
        public async Task<ActionResult> DownloadAlldocsAPI(int PersonalRowID, int SubCheckRowID, string CompanyRefno)
        {
            ClientCustomize cc = new ClientCustomize();
            string Zipname = "";

            DataTable dt = cc.Sp_GetPQVerifiedUploadDocs(PersonalRowID, Convert.ToInt16(SubCheckRowID));


            if (dt == null || dt.Rows.Count == 0)
            {
                return Json(new
                {
                    success = false,
                    message = "No documents found to download."
                }, JsonRequestBehavior.AllowGet);
            }



            using (var memoryStream = new MemoryStream())
            {
                using (var zipArchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                {
                    Zipname = CompanyRefno + "-" + "Documents.zip";
                    foreach (DataRow row in dt.Rows)
                    {
                        // Replace "FilePath" with your actual column name
                        string FileName = row["FileName"].ToString();
                        string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["provideddocuments"].ToString();
                        string filePath = Server.MapPath(FldPathDoc + FileName);
                        if (System.IO.File.Exists(filePath))
                        {
                            string fileName = Path.GetFileName(filePath);

                            var entry = zipArchive.CreateEntry(fileName, CompressionLevel.Fastest);

                            using (var entryStream = entry.Open())
                            using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
                            {
                                await fileStream.CopyToAsync(entryStream);
                            }
                        }
                    }
                }

                memoryStream.Position = 0;

                return File(memoryStream.ToArray(), "application/zip", Zipname);
            }
        }

