        public bool Convert_PNGtoJPG_SpecificFile(string sourcePath, string destinationPath)
        {
            // 1. Define the specific location of your source PNG and destination JPG
            //string sourcePath = Server.MapPath("~/Images/source-image.png");
            //string destinationPath = Server.MapPath("~/Images/converted-image.jpg");

            // Check if the source file actually exists
            if (!System.IO.File.Exists(sourcePath))
            {
                return false;
            }

            using (var originalBitmap = new Bitmap(sourcePath))
            {
                // OPTIONAL STEP: Resize dimensions to further reduce file size (e.g., reduce width/height by 50%)
                // If you want to keep the exact same dimensions, skip resizing and use 'originalBitmap' directly.
                int newWidth = originalBitmap.Width;   // Keep original width
                int newHeight = originalBitmap.Height; // Keep original height

                // Uncomment lines below if you want to scale down dimensions by half:
                // int newWidth = originalBitmap.Width / 2;
                // int newHeight = originalBitmap.Height / 2;

                using (var resizedBitmap = new Bitmap(originalBitmap, newWidth, newHeight))
                {
                    // Create white background for transparent PNGs
                    using (var finalBitmap = new Bitmap(newWidth, newHeight))
                    {
                        using (var graphics = Graphics.FromImage(finalBitmap))
                        {
                            graphics.Clear(Color.White);
                            graphics.DrawImage(resizedBitmap, 0, 0, newWidth, newHeight);
                        }

                        // 2. Configure Encoder Parameters for file size compression
                        EncoderParameters encoderParams = new EncoderParameters(1);

                        // Set quality level from 0L to 100L. 
                        // 75L is a great sweet spot for a massive drop in file size with minimal visual loss.
                        encoderParams.Param[0] = new EncoderParameter(System.Drawing.Imaging.Encoder.Quality, 75L);
                        ImageCodecInfo jpegCodec = GetEncoderInfo(ImageFormat.Jpeg);

                        // 3. Save to destination path
                        if (jpegCodec != null)
                        {
                            finalBitmap.Save(destinationPath, jpegCodec, encoderParams);
                        }
                        else
                        {
                            finalBitmap.Save(destinationPath, ImageFormat.Jpeg);
                        }
                    }
                }
            }
            return true;
        }

        private ImageCodecInfo GetEncoderInfo(ImageFormat format)
        {
            ImageCodecInfo[] codecs = ImageCodecInfo.GetImageEncoders();
            foreach (ImageCodecInfo codec in codecs)
            {
                if (codec.FormatID == format.Guid)
                {
                    return codec;
                }
            }
            return null;
        }

